B.abK=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u0628\u0643\u0631 \u0627\u0644\u0635\u062f\u064a\u0642: "\u0623\u062d\u0628\u064f\u0651 \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u0623\u062f\u0648\u0645\u0647\u0627 \u0648\u0625\u0646 \u0642\u0644\u064e\u0651."','\u0626\u06d5\u0628\u0648\u0628\u06d5\u06a9\u0631 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u062d\u06d5\u0632\u06a9\u0631\u0627\u0648\u062a\u0631\u06cc\u0646 \u06a9\u0631\u062f\u0627\u0631 \u0644\u0627\u06cc \u062e\u0648\u0627 \u0628\u06d5\u0631\u062f\u06d5\u0648\u0627\u0645\u062a\u0631\u06cc\u0646\u06cc\u0627\u0646\u06d5."','Abu Bakr said: "The deeds most beloved to Allah are the most consistent."'],t.w)
B.aaZ=new A.C(B.r,['\u0642\u0627\u0644 \u0639\u0644\u064a \u0628\u0646 \u0623\u0628\u064a \u0637\u0627\u0644\u0628: "\u0644\u0627 \u062a\u0633\u062a\u062d\u0650 \u0645\u0646 \u0625\u0639\u0637\u0627\u0621 \u0627\u0644\u0642\u0644\u064a\u0644\u060c \u0641\u0625\u0646 \u0627\u0644\u062d\u0631\u0645\u0627\u0646 \u0623\u0642\u0644\u064f\u0651 \u0645\u0646\u0647."','\u0639\u06d5\u0644\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0634\u06d5\u0631\u0645 \u0645\u06d5\u06a9\u06d5 \u0644\u06d5 \u062f\u0627\u0646\u06cc \u06a9\u06d5\u0645\u060c \u0686\u0648\u0646\u06a9\u06d5 \u0646\u06d5\u062f\u0627\u0646 \u06a9\u06d5\u0645\u062a\u0631\u06d5."','Ali said: "Do not be ashamed of giving little, for deprivation is less."'],t.w)
B.a9Q=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u062d\u0633\u0646 \u0627\u0644\u0628\u0635\u0631\u064a: "\u064a\u0627 \u0627\u0628\u0646 \u0622\u062f\u0645\u060c \u0625\u0646\u0645\u0627 \u0623\u0646\u062a \u0623\u064a\u0627\u0645\u060c \u0643\u0644\u0645\u0627 \u0630\u0647\u0628 \u064a\u0648\u0645 \u0630\u0647\u0628 \u0628\u0639\u0636\u0643."','\u062d\u06d5\u0633\u06d5\u0646\u06cc \u0628\u06d5\u0633\u0631\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u06cc \u0626\u0627\u062f\u06d5\u0645\u06cc\u0632\u0627\u062f\u060c \u062a\u06c6 \u0695\u06c6\u0698\u0627\u0646\u06cc\u062a\u060c \u0647\u06d5\u0631 \u0695\u06c6\u0698\u06ce\u06a9 \u0628\u0686\u06ce\u062a \u0628\u06d5\u0634\u06ce\u06a9\u062a \u062f\u06d5\u0686\u06ce\u062a."','Al-Hasan said: "O son of Adam, you are but days."'],t.w)
B.abv=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0645\u0633\u0639\u0648\u062f: "\u0645\u0646 \u0623\u0631\u0627\u062f \u0627\u0644\u0622\u062e\u0631\u0629 \u0623\u0636\u0631\u064e\u0651 \u0628\u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0641\u0623\u0636\u0650\u0631\u064f\u0651\u0648\u0627 \u0628\u0627\u0644\u0641\u0627\u0646\u064a \u0644\u0644\u0628\u0627\u0642\u064a."','\u0627\u0628\u0646 \u0645\u06d5\u0633\u0639\u0648\u062f \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0632\u06cc\u0627\u0646 \u0628\u06d5 \u0646\u06d5\u0645\u0627\u0646\u06d5\u0648\u06d5 \u0628\u06af\u06d5\u06cc\u06d5\u0646\u0646 \u0628\u06c6 \u0645\u0627\u0646\u06d5\u0648\u06d5."','Ibn Masud said: "Harm the temporary for the eternal."'],t.w)
B.ace=new A.C(B.r,['\u0642\u0627\u0644 \u0633\u0641\u064a\u0627\u0646 \u0627\u0644\u062b\u0648\u0631\u064a: "\u0645\u0627 \u0639\u0627\u0644\u062c\u062a\u064f \u0634\u064a\u0626\u0627\u064b \u0623\u0634\u062f\u064e\u0651 \u0639\u0644\u064a\u064e\u0651 \u0645\u0646 \u0646\u0641\u0633\u064a."','\u0633\u0648\u0641\u06cc\u0627\u0646 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0647\u06cc\u0686\u0645 \u0642\u0648\u0631\u0633\u062a\u0631 \u0646\u06d5\u0628\u0648\u0648 \u0644\u06d5 \u062e\u06c6\u0645."','Sufyan said: "Nothing was harder for me than my own self."'],t.w)
B.act=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u0641\u0636\u064a\u0644 \u0628\u0646 \u0639\u064a\u0627\u0636: "\u0625\u0630\u0627 \u0644\u0645 \u062a\u0642\u062f\u0631 \u0639\u0644\u0649 \u0642\u064a\u0627\u0645 \u0627\u0644\u0644\u064a\u0644 \u0641\u0627\u0639\u0644\u0645 \u0623\u0646\u0643 \u0645\u062d\u0631\u0648\u0645."','\u0641\u0648\u0632\u06d5\u06cc\u0644 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u06af\u06d5\u0631 \u0646\u06d5\u062a\u062a\u0648\u0627\u0646\u06cc \u0634\u06d5\u0648 \u0695\u0627\u0628\u0648\u06d5\u0633\u062a\u06cc\u062a\u060c \u0628\u0632\u0627\u0646\u06d5 \u0628\u06ce\u0628\u06d5\u0634\u06cc\u062a."','Fudayl said: "If you cannot pray at night, know you are deprived."'],t.w)
B.ab4=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0627\u0644\u0642\u064a\u0645: "\u0627\u0644\u0642\u0644\u0628 \u064a\u0645\u0631\u0636 \u0643\u0645\u0627 \u064a\u0645\u0631\u0636 \u0627\u0644\u0628\u062f\u0646\u060c \u0648\u0634\u0641\u0627\u0624\u0647 \u0641\u064a \u0627\u0644\u062a\u0648\u0628\u0629."','\u0627\u0628\u0646 \u0642\u06d5\u06cc\u0645 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u062f\u06b5 \u0646\u06d5\u062e\u06c6\u0634 \u062f\u06d5\u0628\u06ce\u062a \u0648\u06d5\u06a9 \u062c\u06d5\u0633\u062a\u06d5\u060c \u0686\u0627\u06a9\u0628\u0648\u0648\u0646\u06cc \u0644\u06d5 \u062a\u06d5\u0648\u0628\u06d5\u06cc\u06d5."','Ibn al-Qayyim said: "The heart gets sick like the body, its cure is repentance."'],t.w)
B.acw=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u0634\u0627\u0641\u0639\u064a: "\u0645\u0646 \u0644\u0645 \u062a\u064f\u0639\u0632\u0650\u0651\u0647 \u0627\u0644\u062a\u0642\u0648\u0649 \u0641\u0644\u0627 \u0639\u0632 \u0644\u0647."','\u0634\u0627\u0641\u0639\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u062a\u06d5\u0642\u0648\u0627 \u0633\u06d5\u0631\u0628\u06d5\u0631\u0632\u06cc \u0646\u06d5\u06a9\u0627\u062a\u060c \u0633\u06d5\u0631\u0628\u06d5\u0631\u0632\u06cc \u0646\u06cc\u06cc\u06d5."','Al-Shafi said: "Whoever is not honored by piety has no honor."'],t.w)
