B.aaz=new A.C(B.r,['\u0642\u0627\u0644 \u0639\u062b\u0645\u0627\u0646 \u0628\u0646 \u0639\u0641\u0627\u0646: "\u0644\u0648 \u0637\u0647\u0631\u062a \u0642\u0644\u0648\u0628\u0643\u0645 \u0645\u0627 \u0634\u0628\u0639\u062a\u0645 \u0645\u0646 \u0643\u0644\u0627\u0645 \u0627\u0644\u0644\u0647."','\u0639\u0648\u0633\u0645\u0627\u0646 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u06af\u06d5\u0631 \u062f\u06b5\u062a\u0627\u0646 \u067e\u0627\u06a9 \u0628\u0648\u0627\u06cc\u06d5\u060c \u062a\u06ce\u0631 \u0646\u06d5\u062f\u06d5\u0628\u0648\u0648\u0646 \u0644\u06d5 \u0642\u0648\u0631\u0626\u0627\u0646."','Uthman said: "If your hearts were pure, you would never tire of Quran."'],t.w)
B.abk=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0639\u0628\u0627\u0633: "\u0645\u0627 \u0623\u0646\u0639\u0645 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0639\u0628\u062f \u0646\u0639\u0645\u0629 \u0623\u0639\u0638\u0645 \u0645\u0646 \u0623\u0646 \u064a\u0644\u0647\u0645\u0647 \u0630\u0643\u0631\u0647."','\u0627\u0628\u0646 \u0639\u06d5\u0628\u0627\u0633 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0647\u06cc\u0686 \u0646\u06cc\u0639\u0645\u06d5\u062a\u06ce\u06a9 \u06af\u06d5\u0648\u0631\u06d5\u062a\u0631 \u0646\u06cc\u06cc\u06d5 \u0644\u06d5 \u06cc\u0627\u062f\u06cc \u062e\u0648\u0627."','Ibn Abbas said: "No blessing is greater than being inspired to remember Allah."'],t.w)
B.abQ=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u0625\u0645\u0627\u0645 \u0645\u0627\u0644\u0643: "\u0627\u0644\u0633\u0646\u0629 \u0633\u0641\u064a\u0646\u0629 \u0646\u0648\u062d\u060c \u0645\u0646 \u0631\u0643\u0628\u0647\u0627 \u0646\u062c\u0627."','\u0626\u06cc\u0645\u0627\u0645 \u0645\u0627\u0644\u06a9 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0633\u0648\u0646\u0646\u06d5\u062a \u06a9\u06d5\u0634\u062a\u06cc\u06cc \u0646\u0648\u062d\u06d5\u060c \u0647\u06d5\u0631\u06a9\u06d5\u0633\u06ce\u06a9 \u0633\u0648\u0627\u0631\u06cc \u0628\u06ce\u062a \u0695\u0632\u06af\u0627\u0631 \u062f\u06d5\u0628\u06ce\u062a."','Imam Malik said: "The Sunnah is Noah ark, whoever boards it is saved."'],t.w)
B.aap=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0627\u0644\u062c\u0648\u0632\u064a: "\u0627\u0644\u0639\u0645\u0631 \u0642\u0635\u064a\u0631 \u0641\u0644\u0627 \u062a\u0642\u0635\u0631\u0647 \u0628\u0627\u0644\u063a\u0641\u0644\u0629."','\u0627\u0628\u0646 \u062c\u06d5\u0648\u0632\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u062a\u06d5\u0645\u06d5\u0646 \u06a9\u0648\u0631\u062a\u06d5\u060c \u0628\u06d5 \u063a\u06d5\u0641\u06b5\u06d5\u062a \u06a9\u0648\u0631\u062a\u062a\u0631\u06cc \u0645\u06d5\u06a9\u06d5."','Ibn al-Jawzi said: "Life is short, do not shorten it with heedlessness."'],t.w)
B.aa0=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u0627\u0644\u062f\u0631\u062f\u0627\u0621: "\u062a\u0641\u0643\u0631 \u0633\u0627\u0639\u0629 \u062e\u064a\u0631 \u0645\u0646 \u0642\u064a\u0627\u0645 \u0644\u064a\u0644\u0629."','\u0626\u06d5\u0628\u0648 \u062f\u06d5\u0631\u062f\u0627\u0621 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u06a9\u0627\u062a\u0698\u0645\u06ce\u0631\u06ce\u06a9 \u0628\u06cc\u0631\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5 \u0628\u0627\u0634\u062a\u0631\u06d5 \u0644\u06d5 \u0634\u06d5\u0648\u06ce\u06a9 \u0646\u0648\u06ce\u0698."','Abu Darda said: "An hour of reflection is better than a night of prayer."'],t.w)
B.a9n=new A.C(B.r,['\u0642\u0627\u0644 \u0648\u0647\u0628 \u0628\u0646 \u0645\u0646\u0628\u0647: "\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0639\u0631\u064a\u0627\u0646 \u0648\u0644\u0628\u0627\u0633\u0647 \u0627\u0644\u062a\u0642\u0648\u0649."','\u0648\u06d5\u0647\u0628 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06cc\u0645\u0627\u0646 \u0695\u0648\u0648\u062a\u06d5 \u0648 \u062c\u0644\u06d5\u06a9\u06d5\u06cc \u062a\u06d5\u0642\u0648\u0627\u06cc\u06d5."','Wahb said: "Faith is naked and its clothing is piety."'],t.w)
B.ab8=new A.C(B.r,['\u0642\u0627\u0644 \u0628\u0634\u0631 \u0627\u0644\u062d\u0627\u0641\u064a: "\u0644\u064a\u0633 \u0644\u0644\u0642\u0644\u0628 \u0625\u0644\u0627 \u0648\u062c\u0647\u0629 \u0648\u0627\u062d\u062f\u0629\u060c \u0645\u062a\u0649 \u062a\u0648\u062c\u0647 \u063a\u0641\u0644."','\u0628\u0634\u0631 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u062f\u06b5 \u062a\u06d5\u0646\u0647\u0627 \u06cc\u06d5\u06a9 \u0626\u0627\u0631\u0627\u0633\u062a\u06d5\u06cc \u0647\u06d5\u06cc\u06d5."','Bishr said: "The heart has only one direction."'],t.w)
B.abG=new A.C(B.r,['\u0642\u0627\u0644 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0628\u0646 \u0623\u062f\u0647\u0645: "\u0645\u0627 \u0635\u062f\u0642 \u0627\u0644\u0644\u0647 \u0639\u0628\u062f \u0623\u062d\u0628 \u0627\u0644\u0634\u0647\u0631\u0629."','\u0626\u06cc\u0628\u0631\u0627\u0647\u06cc\u0645 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0647\u06d5\u0631\u06a9\u06d5\u0633\u06ce\u06a9 \u0646\u0627\u0648\u0628\u0627\u0646\u06af\u06cc \u062d\u06d5\u0632 \u0628\u06a9\u0627\u062a \u0695\u0627\u0633\u062a\u06af\u06c6 \u0646\u06cc\u06cc\u06d5 \u0644\u06d5\u06af\u06d5\u06b5 \u062e\u0648\u0627."','Ibrahim said: "No one who loves fame is truthful with Allah."'],t.w)
