B.abg=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u062d\u0646\u064a\u0641\u0629: "\u0625\u0630\u0627 \u0635\u062d \u0627\u0644\u0633\u0646\u062f \u0641\u0647\u0648 \u0645\u0630\u0647\u0628\u064a."','\u0626\u06d5\u0628\u0648 \u062d\u06d5\u0646\u06cc\u0641\u06d5 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u06af\u06d5\u0631 \u0633\u06d5\u0646\u06d5\u062f\u06d5\u06a9\u06d5 \u0695\u0627\u0633\u062a \u0628\u0648\u0648 \u0626\u06d5\u0648\u0627 \u0645\u06d5\u0632\u0647\u06d5\u0628\u0645\u06d5."','Abu Hanifa said: "If the chain is authentic, that is my school."'],t.w)
B.a98=new A.C(B.r,['\u0642\u0627\u0644 \u062d\u0627\u062a\u0645 \u0627\u0644\u0623\u0635\u0645: "\u0644\u0644\u0645\u062e\u0644\u0635 \u062b\u0644\u0627\u062b \u0639\u0644\u0627\u0645\u0627\u062a: \u064a\u0646\u0633\u0649 \u0631\u0624\u064a\u0629 \u0646\u0641\u0633\u0647."','\u062d\u0627\u062a\u0645 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u062f\u06b5\u0633\u06c6\u0632 \u0633\u06ce \u0646\u06cc\u0634\u0627\u0646\u06d5\u06cc \u0647\u06d5\u06cc\u06d5: \u062e\u06c6\u06cc \u0644\u06d5\u0628\u06cc\u0631 \u062f\u06d5\u0686\u06ce\u062a."','Hatim said: "The sincere has three signs: he forgets himself."'],t.w)
B.a99=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u062d\u0632\u0645: "\u0627\u0644\u0648\u0642\u062a \u0623\u0639\u0632 \u0645\u0646 \u0623\u0646 \u064a\u0636\u0627\u0639 \u0641\u064a \u062e\u0635\u0648\u0645\u0629."','\u0627\u0628\u0646 \u062d\u06d5\u0632\u0645 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u06a9\u0627\u062a \u0628\u06d5\u0646\u0631\u062e\u062a\u0631\u06d5 \u0644\u06d5\u0648\u06d5\u06cc \u0628\u06d5 \u06a9\u06ce\u0634\u06d5 \u0628\u06d5\u0641\u06cc\u0695\u06c6 \u0628\u062f\u06d5\u06cc\u062a."','Ibn Hazm said: "Time is too precious to waste in disputes."'],t.w)
B.ab5=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u063a\u0632\u0627\u0644\u064a: "\u0627\u0644\u0639\u0644\u0645 \u0628\u0644\u0627 \u0639\u0645\u0644 \u062c\u0646\u0648\u0646\u060c \u0648\u0627\u0644\u0639\u0645\u0644 \u0628\u0644\u0627 \u0639\u0644\u0645 \u0644\u0627 \u064a\u0643\u0648\u0646."','\u063a\u06d5\u0632\u0627\u0644\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0632\u0627\u0646\u0633\u062a \u0628\u06d5\u0628\u06ce \u06a9\u0631\u062f\u0627\u0631 \u0634\u06ce\u062a\u06cc\u06cc\u06d5."','Al-Ghazali said: "Knowledge without action is madness."'],t.w)
