B.abI=new A.C(B.r,['\u0642\u0627\u0644 \u064a\u062d\u064a\u0649 \u0628\u0646 \u0645\u0639\u0627\u0630: "\u0645\u0646 \u0639\u0631\u0641 \u0627\u0644\u0644\u0647 \u0623\u062d\u0628\u0647\u060c \u0648\u0645\u0646 \u0623\u062d\u0628\u0647 \u0627\u0633\u062a\u0623\u0646\u0633 \u0628\u0647."','\u06cc\u06d5\u062d\u06cc\u0627 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u062e\u0648\u0627 \u0628\u0646\u0627\u0633\u06ce\u062a \u062d\u06d5\u0632\u06cc \u0644\u06ce \u062f\u06d5\u06a9\u0627\u062a\u060c \u0626\u06d5\u0648\u06d5\u06cc \u062d\u06d5\u0632\u06cc \u0644\u06ce \u0628\u06a9\u0627\u062a \u067e\u06ce\u06cc \u0626\u0627\u0634\u0646\u0627 \u062f\u06d5\u0628\u06ce\u062a."','Yahya said: "Who knows Allah loves Him, who loves Him finds comfort in Him."'],t.w)
B.ac9=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u064a\u0632\u064a\u062f \u0627\u0644\u0628\u0633\u0637\u0627\u0645\u064a: "\u0623\u0639\u0638\u0645 \u0627\u0644\u0643\u0631\u0627\u0645\u0627\u062a \u0627\u0644\u0627\u0633\u062a\u0642\u0627\u0645\u0629."','\u0626\u06d5\u0628\u0648 \u06cc\u06d5\u0632\u06cc\u062f \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u06af\u06d5\u0648\u0631\u06d5\u062a\u0631\u06cc\u0646 \u06a9\u06d5\u0631\u0627\u0645\u06d5\u062a \u0695\u0627\u0633\u062a\u0628\u0648\u0648\u0646\u06d5."','Abu Yazid said: "The greatest miracle is uprightness."'],t.w)
B.aan=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u062d\u0627\u0631\u062b \u0627\u0644\u0645\u062d\u0627\u0633\u0628\u064a: "\u0645\u0646 \u0644\u0645 \u064a\u0639\u0631\u0641 \u0646\u0641\u0633\u0647 \u0644\u0627 \u064a\u0639\u0631\u0641 \u0631\u0628\u0647."','\u062d\u0627\u0631\u0633 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u062e\u06c6\u06cc \u0646\u06d5\u0646\u0627\u0633\u06ce\u062a \u062e\u0648\u0627\u0634\u06cc \u0646\u0627\u0646\u0627\u0633\u06ce\u062a."','Al-Harith said: "Who does not know himself does not know his Lord."'],t.w)
B.abz=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u0633\u0631\u064a \u0627\u0644\u0633\u0642\u0637\u064a: "\u0627\u0644\u062a\u0635\u0648\u0641 \u0627\u0633\u0645 \u0644\u062b\u0644\u0627\u062b: \u0644\u0627 \u062a\u0637\u0641\u0626 \u0646\u0648\u0631\u0647 \u0646\u0648\u0631 \u0646\u0641\u0633\u0647."','\u0633\u06d5\u0631\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u062a\u06d5\u0633\u06d5\u0648\u0641 \u0633\u06ce \u0634\u062a\u06d5: \u0695\u0648\u0646\u0627\u06a9\u06cc\u06d5\u06a9\u06d5\u06cc \u0628\u06d5 \u0695\u0648\u0648\u0646\u0627\u06a9\u06cc\u06cc\u06d5\u06a9\u06d5\u06cc \u0695\u06c6\u062d\u06cc \u0646\u0627\u062f\u06d5\u0633\u0695\u06ce\u062a\u06d5\u0648\u06d5."','Al-Sari said: "Sufism is three things: its light is not extinguished."'],t.w)
B.a8h=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u0639\u0645\u0631\u0627\u0646 \u0627\u0644\u062c\u0648\u0646\u064a: "\u0627\u0644\u062f\u0646\u064a\u0627 \u062e\u0645\u0631 \u0627\u0644\u0634\u064a\u0637\u0627\u0646\u060c \u0645\u0646 \u0633\u0643\u0631 \u0628\u0647\u0627 \u0644\u0645 \u064a\u0641\u0642 \u0625\u0644\u0627 \u0628\u064a\u0646 \u064a\u062f\u064a \u0627\u0644\u0644\u0647."','\u0626\u06d5\u0628\u0648 \u0639\u0645\u0631\u0627\u0646 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u062f\u0648\u0646\u06cc\u0627 \u0634\u06d5\u0631\u0627\u0628\u06cc \u0634\u06d5\u06cc\u062a\u0627\u0646\u06d5\u060c \u0647\u06d5\u0631\u06a9\u06d5\u0633\u06ce\u06a9 \u0633\u06d5\u0631\u062e\u06c6\u0634 \u0628\u06a9\u0627\u062a \u0628\u06d5 \u0647\u06c6\u06a9\u06d5\u06cc \u062a\u06d5\u0646\u0647\u0627 \u0644\u06d5\u0644\u0627\u06cc \u062e\u0648\u0627 \u0628\u06d5\u0647\u06c6\u0634 \u062f\u06ce\u062a\u06d5\u0648\u06d5."','Abu Imran said: "The world is the devil wine; whoever gets drunk only wakes before Allah."'],t.w)
B.aah=new A.C(B.r,['\u0642\u0627\u0644 \u0639\u0627\u0645\u0631 \u0628\u0646 \u0639\u0628\u062f \u0642\u064a\u0633: "\u0645\u0646 \u0623\u0643\u062b\u0631 \u0645\u0646 \u0630\u0643\u0631 \u0627\u0644\u0645\u0648\u062a \u0647\u0627\u0646\u062a \u0639\u0644\u064a\u0647 \u0645\u0635\u0627\u0626\u0628 \u0627\u0644\u062f\u0646\u064a\u0627."','\u0639\u0627\u0645\u0631 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0647\u06d5\u0631\u06a9\u06d5\u0633\u06ce\u06a9 \u0632\u06c6\u0631 \u06cc\u0627\u062f\u06cc \u0645\u06d5\u0631\u06af \u0628\u06a9\u0627\u062a \u0628\u06d5\u06b5\u0627\u06a9\u0627\u0646\u06cc \u062f\u0648\u0646\u06cc\u0627 \u0633\u0648\u0648\u06a9 \u062f\u06d5\u0628\u0646 \u0644\u06d5\u0633\u06d5\u0631\u06cc."','Amir said: "Who remembers death much, worldly calamities become easy."'],t.w)
B.ab9=new A.C(B.r,['\u0642\u0627\u0644 \u062e\u0627\u0644\u062f \u0628\u0646 \u0645\u0639\u062f\u0627\u0646: "\u0645\u0627 \u0645\u0646 \u0622\u062f\u0645\u064a \u0625\u0644\u0627 \u0648\u0644\u0647 \u0635\u0648\u0631\u062a\u0627\u0646: \u0635\u0648\u0631\u0629 \u0623\u0645\u0627\u0645 \u0627\u0644\u0646\u0627\u0633 \u0648\u0635\u0648\u0631\u0629 \u0641\u064a \u0627\u0644\u062e\u0644\u0648\u0629."','\u062e\u0627\u0644\u062f \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0647\u06cc\u0686 \u0626\u0627\u062f\u06d5\u0645\u06cc\u0632\u0627\u062f\u06ce\u06a9 \u0646\u06cc\u06cc\u06d5 \u062c\u06af\u06d5 \u0644\u06d5\u0648\u06d5\u06cc \u062f\u0648\u0648 \u0648\u06ce\u0646\u06d5\u06cc \u0647\u06d5\u0628\u06ce\u062a: \u0648\u06ce\u0646\u06d5\u06cc\u06d5\u06a9 \u0644\u06d5\u0628\u06d5\u0631\u062f\u06d5\u0645 \u062e\u06d5\u06b5\u06a9 \u0648 \u06cc\u06d5\u06a9\u06cc\u0634 \u0644\u06d5 \u062a\u06d5\u0646\u0647\u0627\u06cc\u06cc."','Khalid said: "Everyone has two images: one before people and one in solitude."'],t.w)
B.a9K=new A.C(B.r,['\u0642\u0627\u0644 \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0628\u0646 \u0627\u0644\u0645\u0628\u0627\u0631\u0643: "\u0631\u0628 \u0639\u0645\u0644 \u0635\u063a\u064a\u0631 \u062a\u0639\u0638\u0645\u0647 \u0627\u0644\u0646\u064a\u0629."','\u0639\u06d5\u0628\u062f\u0648\u0644\u0644\u0627 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0686\u06d5\u0646\u062f\u06d5 \u06a9\u0631\u062f\u0627\u0631\u06ce\u06a9\u06cc \u0628\u0686\u0648\u0648\u06a9 \u0628\u06d5 \u0646\u06cc\u06d5\u062a \u06af\u06d5\u0648\u0631\u06d5 \u062f\u06d5\u0628\u06ce\u062a."','Abdullah said: "How many small deeds are made great by intention."'],t.w)
B.a94=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u0641\u0636\u064a\u0644: "\u0627\u0644\u0645\u0624\u0645\u0646 \u0642\u0644\u064a\u0644 \u0627\u0644\u0643\u0644\u0627\u0645 \u0643\u062b\u064a\u0631 \u0627\u0644\u0639\u0645\u0644."','\u0641\u0648\u0632\u06d5\u06cc\u0644 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0628\u0627\u0648\u06d5\u0695\u062f\u0627\u0631 \u06a9\u06d5\u0645 \u0642\u0633\u06d5\u06cc\u06d5 \u0648 \u0632\u06c6\u0631 \u06a9\u0631\u062f\u0627\u0631\u06d5."','Fudayl said: "The believer speaks little and acts much."'],t.w)
B.a9D=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u062d\u0627\u0632\u0645: "\u0645\u0627 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0634\u064a\u0621 \u064a\u0633\u0631\u0643 \u0625\u0644\u0627 \u0648\u0642\u062f \u0623\u0644\u0635\u0642 \u0628\u0647 \u0634\u064a\u0621 \u064a\u0633\u0648\u0621\u0643."','\u0626\u06d5\u0628\u0648 \u062d\u0627\u0632\u0645 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0647\u06cc\u0686 \u0634\u062a\u06ce\u06a9 \u0646\u06cc\u06cc\u06d5 \u0644\u06d5 \u062f\u0648\u0646\u06cc\u0627 \u062f\u06b5\u062a \u062e\u06c6\u0634 \u0628\u06a9\u0627\u062a \u062c\u06af\u06d5 \u0644\u06d5\u0648\u06d5\u06cc \u0634\u062a\u06ce\u06a9\u06cc \u0646\u0627\u062e\u06c6\u0634\u06cc \u067e\u06ce\u0648\u06d5 \u0628\u0686\u06d5\u0633\u067e\u06ce\u062a."','Abu Hazim said: "Nothing in the world pleases you except that something sad is attached."'],t.w)
B.a91=new A.C(B.r,['\u0642\u0627\u0644 \u0639\u0648\u0646 \u0628\u0646 \u0639\u0628\u062f\u0627\u0644\u0644\u0647: "\u0643\u0645 \u0645\u0646 \u0645\u0633\u062a\u0642\u0628\u0644 \u064a\u0648\u0645\u0627\u064b \u0644\u0627 \u064a\u0633\u062a\u0643\u0645\u0644\u0647."','\u0639\u06d5\u0648\u0646 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0686\u06d5\u0646\u062f\u06d5 \u06a9\u06d5\u0633\u06ce\u06a9 \u0695\u06c6\u0698\u06ce\u06a9 \u067e\u06ce\u0634\u0648\u0627\u0632\u06cc \u062f\u06d5\u06a9\u0627\u062a \u0648 \u062a\u06d5\u0648\u0627\u0648\u06cc \u0646\u0627\u06a9\u0627\u062a."','Awn said: "How many welcome a day but do not complete it."'],t.w)
B.abM=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0634\u064f\u0628\u0631\u0645\u0629: "\u0639\u062c\u0628\u062a \u0644\u0645\u0646 \u064a\u062d\u062a\u0645\u064a \u0645\u0646 \u0627\u0644\u0637\u0639\u0627\u0645 \u0644\u0645\u0636\u0631\u062a\u0647\u060c \u0648\u0644\u0627 \u064a\u062d\u062a\u0645\u064a \u0645\u0646 \u0627\u0644\u0630\u0646\u0628 \u0644\u0645\u0639\u0631\u062a\u0647."','\u0627\u0628\u0646 \u0634\u0648\u0628\u0631\u0648\u0645\u06d5 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0633\u06d5\u0631\u0645 \u0633\u0648\u0695\u0645\u0627\u06cc\u06d5\u0648\u06d5 \u0644\u06d5\u0648\u06d5\u06cc \u067e\u06d5\u0631\u0647\u06ce\u0632 \u062f\u06d5\u06a9\u0627\u062a \u0644\u06d5 \u062e\u0648\u0627\u0631\u062f\u0646 \u0628\u06c6 \u0632\u06cc\u0627\u0646\u06d5\u06a9\u06d5\u06cc\u060c \u0628\u06d5\u06b5\u0627\u0645 \u067e\u06d5\u0631\u0647\u06ce\u0632 \u0646\u0627\u06a9\u0627\u062a \u0644\u06d5 \u06af\u0648\u0646\u0627\u0647 \u0628\u06c6 \u0695\u06cc\u0633\u0648\u0627\u06cc\u06d5\u06a9\u06d5\u06cc."','Ibn Shubrumah said: "I am amazed at who avoids harmful food but not sinful deeds."'],t.w)
B.ab7=new A.C(B.r,['\u0642\u0627\u0644 \u0645\u062d\u0645\u062f \u0628\u0646 \u0648\u0627\u0633\u0639: "\u0645\u0627 \u062a\u0644\u0630\u0630\u062a \u0628\u0634\u064a\u0621 \u0643\u062a\u0644\u0630\u0630\u064a \u0628\u0627\u0644\u062a\u0647\u062c\u062f \u0641\u064a \u062c\u0648\u0641 \u0627\u0644\u0644\u064a\u0644."','\u0645\u062d\u06d5\u0645\u0645\u06d5\u062f \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0628\u06d5 \u0647\u06cc\u0686 \u0634\u062a\u06ce\u06a9 \u062a\u0627\u0645 \u0646\u06d5\u0628\u0631\u062f\u0648\u0648\u0645 \u0648\u06d5\u06a9 \u062a\u06d5\u0647\u06d5\u062c\u062c\u0648\u062f \u0644\u06d5 \u0646\u0627\u0648\u06d5\u0695\u0627\u0633\u062a\u06cc \u0634\u06d5\u0648."','Muhammad said: "I have not enjoyed anything like night prayer."'],t.w)
B.aav=new A.C(B.r,['\u0642\u0627\u0644 \u0645\u0627\u0644\u0643 \u0628\u0646 \u062f\u064a\u0646\u0627\u0631: "\u0627\u062a\u062e\u0630 \u0627\u0644\u0644\u0647 \u0635\u0627\u062d\u0628\u0627\u064b \u0648\u062f\u0639 \u0627\u0644\u0646\u0627\u0633 \u062c\u0627\u0646\u0628\u0627\u064b."','\u0645\u0627\u0644\u06a9 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u062e\u0648\u0627 \u0628\u06a9\u06d5 \u0628\u06d5 \u0647\u0627\u0648\u0695\u06ce \u0648 \u062e\u06d5\u06b5\u06a9 \u0628\u0647\u06ce\u06b5\u06d5\u0631\u06d5\u0648\u06d5 \u0644\u0627."','Malik said: "Take Allah as companion and leave people aside."'],t.w)
B.abf=new A.C(B.r,['\u0642\u0627\u0644 \u0645\u0646\u0635\u0648\u0631 \u0628\u0646 \u0632\u0627\u0630\u0627\u0646: "\u0645\u0627 \u0628\u0643\u064a\u062a \u0645\u0646 \u062e\u0634\u064a\u0629 \u0627\u0644\u0644\u0647 \u0642\u0637 \u0625\u0644\u0627 \u0632\u0627\u062f\u0646\u064a \u0630\u0644\u0643 \u0625\u064a\u0645\u0627\u0646\u0627\u064b."','\u0645\u06d5\u0646\u0633\u0648\u0648\u0631 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0647\u06d5\u0631\u06af\u06cc\u0632 \u0644\u06d5 \u062a\u0631\u0633\u06cc \u062e\u0648\u0627 \u0646\u06d5\u06af\u0631\u06cc\u0627\u0645 \u062c\u06af\u06d5 \u0644\u06d5\u0648\u06d5\u06cc \u0626\u06cc\u0645\u0627\u0646\u0645 \u0632\u06c6\u0631\u062a\u0631 \u0628\u06a9\u0627\u062a."','Mansur said: "I never cried from fear of Allah except it increased my faith."'],t.w)
B.a9l=new A.C(B.r,['\u0642\u0627\u0644 \u062d\u0628\u064a\u0628 \u0627\u0644\u0639\u062c\u0645\u064a: "\u0625\u0630\u0627 \u0623\u0631\u062f\u062a \u0623\u0646 \u062a\u0639\u0631\u0641 \u0642\u062f\u0631\u0643 \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u0641\u0627\u0646\u0638\u0631 \u0641\u064a\u0645\u0627 \u0623\u0642\u0627\u0645\u0643."','\u062d\u06d5\u0628\u06cc\u0628 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u06af\u06d5\u0631 \u062f\u06d5\u062a\u06d5\u0648\u06ce\u062a \u067e\u06ce\u06af\u06d5\u062a \u0644\u0627\u06cc \u062e\u0648\u0627 \u0628\u0632\u0627\u0646\u06cc\u062a\u060c \u0633\u06d5\u06cc\u0631\u06cc \u0626\u06d5\u0648\u06d5 \u0628\u06a9\u06d5 \u0644\u06d5 \u0686\u06cc\u062a \u062f\u0627\u0646\u0627\u0648\u06d5."','Habib said: "If you want to know your value with Allah, look at what He has placed you in."'],t.w)
B.aaP=new A.C(B.r,['\u0642\u0627\u0644 \u0639\u062a\u0628\u0629 \u0627\u0644\u063a\u0644\u0627\u0645: "\u0627\u062c\u0639\u0644 \u0639\u0645\u0631\u0643 \u0643\u0644\u0647 \u0644\u0644\u0647 \u064a\u0643\u0646 \u0645\u0627 \u0641\u0627\u062a\u0643 \u0623\u0643\u062b\u0631 \u0645\u0645\u0627 \u0646\u0644\u062a."','\u0639\u0648\u062a\u0628\u06d5 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0647\u06d5\u0645\u0648\u0648 \u062a\u06d5\u0645\u06d5\u0646\u06d5\u06a9\u06d5\u062a \u0628\u06c6 \u062e\u0648\u0627 \u0628\u06a9\u06d5\u060c \u0626\u06d5\u0648\u06d5\u06cc \u0644\u06d5\u062f\u06d5\u0633\u062a \u062f\u06d5\u062f\u06d5\u06cc\u062a \u0632\u06cc\u0627\u062a\u0631\u06d5 \u0644\u06d5\u0648\u06d5\u06cc \u0628\u06d5\u062f\u06d5\u0633\u062a \u062f\u06d5\u0647\u06ce\u0646\u06cc\u062a."','Utbah said: "Make your whole life for Allah."'],t.w)
B.aaq=new A.C(B.r,['\u0642\u0627\u0644 \u0634\u0642\u064a\u0642 \u0627\u0644\u0628\u0644\u062e\u064a: "\u0639\u0644\u0627\u0645\u0629 \u0627\u0644\u062a\u0648\u0628\u0629: \u0627\u0644\u0628\u0643\u0627\u0621 \u0639\u0644\u0649 \u0645\u0627 \u0633\u0644\u0641."','\u0634\u06d5\u0642\u06cc\u0642 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0646\u06cc\u0634\u0627\u0646\u06d5\u06cc \u062a\u06d5\u0648\u0628\u06d5: \u06af\u0631\u06cc\u0627\u0646 \u0644\u06d5\u0633\u06d5\u0631 \u0695\u0627\u0628\u0631\u062f\u0648\u0648."','Shaqiq said: "The sign of repentance is crying over the past."'],t.w)
B.abN=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u062d\u0641\u0635 \u0627\u0644\u0646\u064a\u0633\u0627\u0628\u0648\u0631\u064a: "\u0645\u0646 \u0644\u0645 \u064a\u0632\u0646 \u0623\u0641\u0639\u0627\u0644\u0647 \u0628\u0627\u0644\u0643\u062a\u0627\u0628 \u0648\u0627\u0644\u0633\u0646\u0629 \u0644\u0627 \u064a\u0639\u062f \u0641\u0639\u0644\u0647 \u0634\u064a\u0626\u0627\u064b."','\u0626\u06d5\u0628\u0648 \u062d\u06d5\u0641\u0633 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u06a9\u0631\u062f\u0627\u0631\u06d5\u06a9\u0627\u0646\u06cc \u0628\u06d5 \u06a9\u062a\u06ce\u0628 \u0648 \u0633\u0648\u0646\u0646\u06d5\u062a \u06a9\u06ce\u0634 \u0646\u06d5\u06a9\u0627\u062a\u060c \u06a9\u0631\u062f\u0627\u0631\u06d5\u06a9\u06d5\u06cc \u0647\u06cc\u0686 \u0646\u0627\u06cc\u06d5 \u0698\u0645\u0627\u0631."','Abu Hafs said: "Who does not weigh actions by Quran and Sunnah, his deeds count nothing."'],t.w)
B.acq=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u0645\u062d\u0645\u062f \u0627\u0644\u062c\u0631\u064a\u0631\u064a: "\u0645\u0646 \u0644\u0645 \u064a\u0643\u0646 \u0647\u0645\u0647 \u0641\u064a \u0630\u0643\u0631 \u0631\u0628\u0647 \u0641\u0647\u0648 \u0645\u0642\u0637\u0648\u0639."','\u0626\u06d5\u0628\u0648 \u0645\u062d\u06d5\u0645\u0645\u06d5\u062f \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u06cc\u0627\u062f\u06cc \u062e\u0648\u0627\u06cc \u067e\u06ce\u0648\u06d5 \u0646\u06d5\u0628\u06ce\u062a\u060c \u067e\u0686\u0695\u0627\u0648\u06d5."','Abu Muhammad said: "Whose concern is not remembering his Lord is cut off."'],t.w)
B.abU=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u0628\u0643\u0631 \u0627\u0644\u0648\u0631\u0627\u0642: "\u0645\u0627 \u0641\u062a\u062d \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0639\u0628\u062f \u0628\u0627\u0628 \u062e\u064a\u0631 \u0625\u0644\u0627 \u0648\u0641\u062a\u062d \u0639\u0644\u064a\u0647 \u0628\u0627\u0628 \u0628\u0644\u0627\u0621."','\u0626\u06d5\u0628\u0648 \u0628\u06d5\u06a9\u0631 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u062e\u0648\u0627 \u062f\u06d5\u0631\u06af\u0627\u06cc \u0686\u0627\u06a9\u06d5 \u0628\u06c6 \u0628\u06d5\u0646\u062f\u06d5\u06cc\u06d5\u06a9 \u0646\u0627\u06a9\u0627\u062a\u06d5\u0648\u06d5 \u062c\u06af\u06d5 \u0644\u06d5\u0648\u06d5\u06cc \u062f\u06d5\u0631\u06af\u0627\u06cc \u0628\u06d5\u06b5\u0627 \u0628\u06c6 \u0628\u06a9\u0627\u062a\u06d5\u0648\u06d5."','Abu Bakr said: "Allah does not open a door of good except He opens a door of trial."'],t.w)
B.a9N=new A.C(B.r,['\u0642\u0627\u0644 \u0631\u0648\u064a\u0645 \u0627\u0644\u0628\u063a\u062f\u0627\u062f\u064a: "\u0627\u0644\u0635\u0628\u0631 \u062a\u0631\u0643 \u0627\u0644\u0634\u0643\u0648\u0649."','\u0695\u0648\u06d5\u06cc\u0645 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u0627\u0633\u0648\u0648\u062f\u06d5\u06cc\u06cc \u0648\u0627\u0632\u0647\u06ce\u0646\u0627\u0646\u06d5 \u0644\u06d5 \u06af\u0644\u06d5\u06cc\u06cc."','Ruwaym said: "Patience is abandoning complaint."'],t.w)
B.ac5=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u062a\u0631\u0627\u0628 \u0627\u0644\u0646\u062e\u0634\u0628\u064a: "\u0627\u0644\u0641\u0642\u0631 \u0630\u0644 \u0648\u063a\u0646\u0649 \u0648\u0627\u0644\u063a\u0646\u0649 \u0639\u0632 \u0648\u0630\u0644."','\u0626\u06d5\u0628\u0648 \u062a\u0631\u0627\u0628 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0647\u06d5\u0698\u0627\u0631\u06cc \u062e\u0648\u0627\u0631\u06cc \u0648 \u062f\u06d5\u0648\u0644\u06d5\u0645\u06d5\u0646\u062f\u06cc\u06cc\u06d5\u060c \u062f\u06d5\u0648\u0644\u06d5\u0645\u06d5\u0646\u062f\u06cc \u0633\u06d5\u0631\u0628\u06d5\u0631\u0632\u06cc \u0648 \u062e\u0648\u0627\u0631\u06cc\u06cc\u06d5."','Abu Turab said: "Poverty is humility and wealth, wealth is honor and humility."'],t.w)
B.abx=new A.C(B.r,['\u0642\u0627\u0644 \u0639\u0644\u064a \u0628\u0646 \u0633\u0647\u0644 \u0627\u0644\u0623\u0635\u0628\u0647\u0627\u0646\u064a: "\u0627\u0644\u062f\u064a\u0646 \u0643\u0644\u0647 \u062e\u0644\u0642 \u0641\u0645\u0646 \u0632\u0627\u062f \u0639\u0644\u064a\u0643 \u0641\u064a \u0627\u0644\u062e\u0644\u0642 \u0632\u0627\u062f \u0639\u0644\u064a\u0643 \u0641\u064a \u0627\u0644\u062f\u064a\u0646."','\u0639\u06d5\u0644\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u0627\u06cc\u06cc\u0646 \u0647\u06d5\u0645\u0648\u0648 \u0626\u06d5\u062e\u0644\u0627\u0642\u06d5\u060c \u0626\u06d5\u0648\u06d5\u06cc \u0644\u06d5 \u0626\u06d5\u062e\u0644\u0627\u0642 \u0644\u06d5\u062a \u0632\u06cc\u0627\u062a\u0631 \u0628\u06ce\u062a \u0644\u06d5 \u0626\u0627\u06cc\u06cc\u0646 \u0644\u06d5\u062a \u0632\u06cc\u0627\u062a\u0631\u06d5."','Ali said: "Religion is all character; who exceeds you in character exceeds you in religion."'],t.w)
B.aci=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u0628\u0643\u0631 \u0627\u0644\u0643\u062a\u0627\u0646\u064a: "\u0644\u064a\u0633 \u0644\u0644\u0642\u0644\u0648\u0628 \u0632\u064a\u0646\u0629 \u0623\u062d\u0633\u0646 \u0645\u0646 \u0635\u062f\u0642 \u0627\u0644\u062e\u0637\u0627\u0628."','\u0626\u06d5\u0628\u0648 \u0628\u06d5\u06a9\u0631 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0647\u06cc\u0686 \u062c\u0648\u0627\u0646\u06cc\u06cc\u06d5\u06a9 \u0628\u06c6 \u062f\u06b5 \u0628\u0627\u0634\u062a\u0631 \u0646\u06cc\u06cc\u06d5 \u0644\u06d5 \u0695\u0627\u0633\u062a\u06af\u06c6\u06cc\u06cc."','Abu Bakr said: "There is no adornment for hearts better than truthful speech."'],t.w)
B.aae=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u0639\u062b\u0645\u0627\u0646 \u0627\u0644\u062d\u064a\u0631\u064a: "\u0645\u0646 \u0623\u0645\u0651\u0631 \u0627\u0644\u0633\u0646\u0629 \u0639\u0644\u0649 \u0646\u0641\u0633\u0647 \u0646\u0637\u0642 \u0628\u0627\u0644\u062d\u0643\u0645\u0629."','\u0626\u06d5\u0628\u0648 \u0639\u0648\u0633\u0645\u0627\u0646 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u0633\u0648\u0646\u0646\u06d5\u062a \u0644\u06d5\u0633\u06d5\u0631 \u062e\u06c6\u06cc \u062d\u0627\u06a9\u0645 \u0628\u06a9\u0627\u062a\u060c \u0628\u06d5 \u062f\u0627\u0646\u0627\u06cc\u06cc \u0642\u0633\u06d5 \u062f\u06d5\u06a9\u0627\u062a."','Abu Uthman said: "Who makes Sunnah rule over himself speaks wisdom."'],t.w)
B.aa_=new A.C(B.r,['\u0642\u0627\u0644 \u062d\u0645\u062f\u0648\u0646 \u0627\u0644\u0642\u0635\u0627\u0631: "\u0645\u0646 \u0646\u0638\u0631 \u0625\u0644\u0649 \u0627\u0644\u0646\u0627\u0633 \u0628\u0639\u064a\u0646 \u0639\u0644\u0645\u0647 \u0645\u0642\u062a\u0647\u0645."','\u062d\u06d5\u0645\u062f\u0648\u0648\u0646 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u0628\u06d5 \u0686\u0627\u0648\u06cc \u0632\u0627\u0646\u0633\u062a\u06cc \u062e\u06c6\u06cc \u0633\u06d5\u06cc\u0631\u06cc \u062e\u06d5\u06b5\u06a9 \u0628\u06a9\u0627\u062a \u0695\u0642\u06cc \u0644\u06ce \u062f\u06d5\u0628\u06ce\u062a\u06d5\u0648\u06d5."','Hamdun said: "Who looks at people with his knowledge will despise them."'],t.w)
B.abe=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u062a\u0631\u0645\u0630\u064a \u0627\u0644\u062d\u0643\u064a\u0645: "\u0627\u0644\u0639\u0644\u0645 \u0639\u0644\u0645\u0627\u0646: \u0639\u0644\u0645 \u0627\u0644\u0644\u0633\u0627\u0646 \u0648\u0639\u0644\u0645 \u0627\u0644\u0642\u0644\u0628."','\u062a\u06cc\u0631\u0645\u06cc\u0632\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0632\u0627\u0646\u0633\u062a \u062f\u0648\u0648 \u062c\u06c6\u0631\u06d5: \u0632\u0627\u0646\u0633\u062a\u06cc \u0632\u0645\u0627\u0646 \u0648 \u0632\u0627\u0646\u0633\u062a\u06cc \u062f\u06b5."','Al-Tirmidhi said: "Knowledge is two: knowledge of tongue and knowledge of heart."'],t.w)
B.a8Q=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0639\u0637\u0627\u0621: "\u0623\u0641\u0636\u0644 \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0645\u0627 \u0648\u0627\u0641\u0642 \u0627\u0644\u0639\u0644\u0645."','\u0627\u0628\u0646 \u0639\u06d5\u062a\u0627\u0621 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0628\u0627\u0634\u062a\u0631\u06cc\u0646 \u06a9\u0631\u062f\u0627\u0631 \u0626\u06d5\u0648\u06d5\u06cc\u06d5 \u06a9\u06d5 \u0644\u06d5\u06af\u06d5\u06b5 \u0632\u0627\u0646\u0633\u062a \u0628\u06af\u0648\u0646\u062c\u06ce\u062a."','Ibn Ata said: "The best deeds are those that accord with knowledge."'],t.w)
B.abW=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u0628\u0643\u0631 \u0627\u0644\u0634\u0628\u0644\u064a: "\u0645\u0646 \u0644\u0645 \u064a\u062d\u0641\u0638 \u0627\u0644\u062d\u062f\u0648\u062f \u0644\u0645 \u064a\u062f\u062e\u0644 \u0645\u064a\u0627\u062f\u064a\u0646 \u0627\u0644\u0645\u0639\u0627\u0646\u064a."','\u0634\u0628\u0644\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u0633\u0646\u0648\u0648\u0631\u06d5\u06a9\u0627\u0646 \u0646\u06d5\u067e\u0627\u0631\u06ce\u0632\u06ce\u062a\u060c \u0646\u0627\u0686\u06ce\u062a\u0647 \u0646\u0627\u0648 \u0645\u06d5\u06cc\u062f\u0627\u0646\u06cc \u0648\u0627\u062a\u0627\u06a9\u0627\u0646."','Al-Shibli said: "Who does not observe limits does not enter fields of meaning."'],t.w)
B.aad=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0627\u0644\u0633\u0627\u0644\u0645\u064a: "\u0645\u0646 \u0637\u0644\u0628 \u0627\u0644\u0639\u0632 \u0628\u0627\u0644\u0645\u0639\u0635\u064a\u0629 \u0623\u0648\u0631\u062b\u0647 \u0627\u0644\u0644\u0647 \u0627\u0644\u0630\u0644 \u0628\u0627\u0644\u0637\u0627\u0639\u0629."','\u0633\u0627\u0644\u0645\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u0628\u06d5 \u0646\u0627\u0641\u06d5\u0631\u0645\u0627\u0646\u06cc \u0633\u06d5\u0631\u0628\u06d5\u0631\u0632\u06cc \u0628\u0648\u06ce\u062a\u060c \u062e\u0648\u0627 \u0628\u06d5 \u0641\u06d5\u0631\u0645\u0627\u0646\u0628\u06d5\u0631\u06cc \u062e\u0648\u0627\u0631\u06cc\u06cc\u06d5\u06a9\u06d5\u06cc \u062f\u06d5\u0628\u06d5\u062e\u0634\u06ce\u062a."','Al-Salimi said: "Who seeks honor through sin, Allah gives him humiliation through obedience."'],t.w)
B.a9h=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u0646\u0648\u0631\u064a: "\u0644\u064a\u0633 \u0627\u0644\u062a\u0635\u0648\u0641 \u0631\u0633\u0648\u0645\u0627\u064b \u0648\u0639\u0644\u0648\u0645\u0627\u064b \u0648\u0644\u0643\u0646\u0647 \u0623\u062e\u0644\u0627\u0642."','\u0646\u0648\u0648\u0631\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u062a\u06d5\u0633\u06d5\u0648\u0641 \u0634\u06a9\u06b5 \u0648 \u0632\u0627\u0646\u0633\u062a \u0646\u06cc\u06cc\u06d5\u060c \u0626\u06d5\u062e\u0644\u0627\u0642\u06d5."','Al-Nuri said: "Sufism is not forms and knowledge but character."'],t.w)
B.a9O=new A.C(B.r,['\u0642\u0627\u0644 \u0645\u062d\u0645\u062f \u0628\u0646 \u0627\u0644\u0641\u0636\u0644: "\u0630\u0647\u0627\u0628 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0645\u0646 \u0623\u0631\u0628\u0639\u0629: \u0644\u0627 \u064a\u0639\u0645\u0644\u0648\u0646 \u0628\u0645\u0627 \u064a\u0639\u0644\u0645\u0648\u0646."','\u0645\u062d\u06d5\u0645\u0645\u06d5\u062f \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0695\u06c6\u0634\u062a\u0646\u06cc \u0626\u06cc\u0633\u0644\u0627\u0645 \u0644\u06d5 \u0686\u0648\u0627\u0631 \u0634\u062a\u06d5\u0648\u06d5\u06cc\u06d5: \u0628\u06d5\u0648\u06d5\u06cc \u062f\u06d5\u06cc\u0632\u0627\u0646\u0646 \u06a9\u0627\u0631 \u0646\u0627\u06a9\u06d5\u0646."','Muhammad said: "Islam goes from four: they do not act on what they know."'],t.w)
B.a8W=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u0639\u0644\u064a \u0627\u0644\u062c\u0648\u0632\u062c\u0627\u0646\u064a: "\u0645\u0646 \u0646\u0638\u0631 \u0625\u0644\u0649 \u0627\u0644\u062f\u0646\u064a\u0627 \u0628\u0639\u064a\u0646 \u0627\u0644\u0634\u0647\u0648\u0629 \u0639\u0645\u064a \u0639\u0646 \u0627\u0644\u0622\u062e\u0631\u0629."','\u0626\u06d5\u0628\u0648 \u0639\u06d5\u0644\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u0628\u06d5 \u0686\u0627\u0648\u06cc \u0626\u0627\u0631\u06d5\u0632\u0648\u0648 \u0633\u06d5\u06cc\u0631\u06cc \u062f\u0648\u0646\u06cc\u0627 \u0628\u06a9\u0627\u062a \u0644\u06d5 \u062f\u0648\u0627\u0695\u06c6\u0698 \u06a9\u0648\u06ce\u0631 \u062f\u06d5\u0628\u06ce\u062a."','Abu Ali said: "Who looks at the world with desire becomes blind to the hereafter."'],t.w)
B.abJ=new A.C(B.r,['\u0642\u0627\u0644 \u0645\u0645\u0634\u0627\u062f \u0627\u0644\u062f\u064a\u0646\u0648\u0631\u064a: "\u0627\u0644\u0635\u0648\u0641\u064a \u0644\u0627 \u064a\u0634\u0643\u0648 \u0648\u0644\u0627 \u064a\u062a\u0634\u0643\u0649."','\u0645\u06d5\u0645\u0634\u0627\u062f \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0635\u0648\u0641\u06cc \u06af\u0644\u06d5\u06cc\u06cc \u0646\u0627\u06a9\u0627\u062a \u0648 \u0646\u0627\u06b5\u06ce\u0646\u06ce\u062a."','Mamshad said: "The Sufi does not complain."'],t.w)
B.aaa=new A.C(B.r,['\u0642\u0627\u0644 \u064a\u062d\u064a\u0649 \u0628\u0646 \u0645\u0639\u0627\u0630: "\u0645\u0646 \u0627\u0633\u062a\u063a\u0646\u0649 \u0628\u0627\u0644\u0644\u0647 \u0627\u0641\u062a\u0642\u0631 \u0625\u0644\u064a\u0647 \u0643\u0644 \u0634\u064a\u0621."','\u06cc\u06d5\u062d\u06cc\u0627 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u0628\u06d5 \u062e\u0648\u0627 \u0628\u06ce\u0646\u06cc\u0627\u0632 \u0628\u06ce\u062a\u060c \u0647\u06d5\u0645\u0648\u0648 \u0634\u062a\u06ce\u06a9 \u067e\u06ce\u0648\u06cc\u0633\u062a\u06cc\u06cc \u0628\u06d5\u0648 \u062f\u06d5\u0628\u06ce\u062a."','Yahya said: "Who is self-sufficient with Allah, everything needs him."'],t.w)
B.a8g=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u062e\u0631\u0627\u0632: "\u0644\u064a\u0633 \u0628\u064a\u0646 \u0627\u0644\u0639\u0628\u062f \u0648\u0628\u064a\u0646 \u0627\u0644\u0644\u0647 \u062d\u062c\u0627\u0628 \u0623\u063a\u0644\u0638 \u0645\u0646 \u0627\u0644\u0646\u0641\u0633."','\u062e\u06d5\u0695\u0627\u0632 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0647\u06cc\u0686 \u067e\u06d5\u0631\u062f\u06d5\u06cc\u06d5\u06a9 \u0646\u06cc\u06cc\u06d5 \u0644\u06d5\u0646\u06ce\u0648\u0627\u0646 \u0628\u06d5\u0646\u062f\u06d5 \u0648 \u062e\u0648\u0627 \u0642\u06d5\u06b5\u06d5\u0648\u062a\u0631 \u0644\u06d5 \u0646\u06d5\u0641\u0633."','Al-Kharraz said: "No veil between servant and Allah is thicker than the self."'],t.w)
B.abT=new A.C(B.r,['\u0642\u0627\u0644 \u0639\u0645\u0631\u0648 \u0628\u0646 \u0639\u062b\u0645\u0627\u0646: "\u0627\u0644\u0641\u062a\u0648\u0629 \u0623\u0646 \u0644\u0627 \u062a\u0631\u0649 \u0644\u0646\u0641\u0633\u0643 \u0641\u0636\u0644\u0627\u064b \u0639\u0644\u0649 \u063a\u064a\u0631\u0643."','\u0639\u06d5\u0645\u0631\u0648 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0644\u0627\u0648\u06ce\u062a\u06cc \u0626\u06d5\u0648\u06d5\u06cc\u06d5 \u0646\u06d5\u0628\u06cc\u0646\u06cc\u062a \u062e\u06c6\u062a \u0628\u0627\u0634\u062a\u0631 \u0644\u06d5 \u06a9\u06d5\u0633\u06cc \u062a\u0631."','Amr said: "Chivalry is not seeing yourself superior to others."'],t.w)
B.acp=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u0627\u0644\u0642\u0627\u0633\u0645 \u0627\u0644\u062c\u0646\u064a\u062f: "\u0623\u0634\u0631\u0641 \u0643\u0644\u0645\u0629 \u0641\u064a \u0627\u0644\u062a\u0648\u0628\u0629 \u0623\u0646 \u062a\u0646\u0633\u0649 \u0630\u0646\u0628\u0643."','\u062c\u0648\u0646\u06d5\u06cc\u062f \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0634\u06d5\u0631\u06d5\u0641\u062a\u0631\u06cc\u0646 \u0648\u0634\u06d5\u06cc \u062a\u06d5\u0648\u0628\u06d5 \u0626\u06d5\u0648\u06d5\u06cc\u06d5 \u06af\u0648\u0646\u0627\u0647\u06d5\u06a9\u06d5\u062a \u0644\u06d5\u0628\u06cc\u0631 \u0628\u06a9\u06d5\u06cc\u062a."','Junayd said: "The noblest word in repentance is to forget your sin."'],t.w)
B.a9t=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u0633\u0639\u064a\u062f \u0627\u0644\u062e\u0631\u0627\u0632: "\u0645\u0646 \u0638\u0646 \u0623\u0646\u0647 \u064a\u0635\u0644 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u0628\u063a\u064a\u0631 \u0627\u0644\u0644\u0647 \u0641\u0647\u0648 \u0645\u062c\u0646\u0648\u0646."','\u0626\u06d5\u0628\u0648 \u0633\u06d5\u0639\u06cc\u062f \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u067e\u06ce\u06cc \u0648\u0627\u0628\u06ce\u062a \u0628\u06d5\u0628\u06ce \u062e\u0648\u0627 \u062f\u06d5\u06af\u0627\u062a\u06d5 \u062e\u0648\u0627\u060c \u0634\u06ce\u062a\u06d5."','Abu Said said: "Who thinks he reaches Allah without Allah is mad."'],t.w)
B.a9d=new A.C(B.r,['\u0642\u0627\u0644 \u0645\u062d\u0645\u062f \u0628\u0646 \u062e\u0641\u064a\u0641: "\u0645\u0646 \u0643\u0627\u0646 \u0634\u064a\u062e\u0647 \u0627\u0644\u0643\u062a\u0627\u0628 \u0641\u062e\u0637\u0624\u0647 \u0623\u0643\u062b\u0631 \u0645\u0646 \u0635\u0648\u0627\u0628\u0647."','\u0645\u062d\u06d5\u0645\u0645\u06d5\u062f \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u0634\u06ce\u062e\u06d5\u06a9\u06d5\u06cc \u06a9\u062a\u06ce\u0628 \u0628\u06ce\u062a\u060c \u0647\u06d5\u06b5\u06d5\u06cc \u0632\u06c6\u0631\u062a\u0631\u06d5 \u0644\u06d5 \u0695\u0627\u0633\u062a\u06cc."','Muhammad said: "Whose teacher is only books, his errors exceed his correctness."'],t.w)
B.aaw=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u0627\u0644\u062d\u0633\u064a\u0646 \u0627\u0644\u0646\u0648\u0631\u064a: "\u0627\u0644\u0645\u062d\u0628\u0629 \u0646\u0627\u0631 \u062a\u062d\u0631\u0642 \u0643\u0644 \u0645\u0627 \u0633\u0648\u0649 \u0627\u0644\u0645\u062d\u0628\u0648\u0628."','\u0646\u0648\u0648\u0631\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u062e\u06c6\u0634\u06d5\u0648\u06cc\u0633\u062a\u06cc \u0626\u0627\u06af\u0631\u06d5 \u0647\u06d5\u0645\u0648\u0648 \u0634\u062a\u06ce\u06a9 \u062f\u06d5\u0633\u0648\u0648\u062a\u06ce\u0646\u06ce\u062a \u062c\u06af\u06d5 \u0644\u06d5 \u062e\u06c6\u0634\u06d5\u0648\u06cc\u0633\u062a."','Al-Nuri said: "Love is fire that burns everything except the beloved."'],t.w)
B.aa2=new A.C(B.r,['\u0642\u0627\u0644 \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0627\u0644\u062a\u0633\u062a\u0631\u064a: "\u0623\u0635\u0644 \u0627\u0644\u0637\u0627\u0639\u0629 \u0627\u0644\u0648\u0631\u0639 \u0648\u0623\u0635\u0644 \u0627\u0644\u0648\u0631\u0639 \u0627\u0644\u062e\u0648\u0641."','\u0639\u06d5\u0628\u062f\u0648\u0644\u0644\u0627 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0695\u06cc\u0634\u06d5\u06cc \u06af\u0648\u06ce\u0695\u0627\u06cc\u06d5\u06b5\u06cc \u067e\u06d5\u0631\u0647\u06ce\u0632\u06af\u0627\u0631\u06cc\u06d5 \u0648 \u0695\u06cc\u0634\u06d5\u06cc \u067e\u06d5\u0631\u0647\u06ce\u0632\u06af\u0627\u0631\u06cc \u062a\u0631\u0633\u0646."','Abdullah said: "The root of obedience is piety, the root of piety is fear."'],t.w)
B.a8x=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u0628\u0643\u0631 \u0628\u0646 \u0637\u0627\u0647\u0631: "\u0645\u0646 \u0627\u062f\u0639\u0649 \u0645\u062d\u0628\u0629 \u0627\u0644\u0644\u0647 \u0648\u0644\u0645 \u064a\u0648\u0627\u0641\u0642\u0647 \u0641\u062f\u0639\u0648\u0627\u0647 \u0628\u0627\u0637\u0644\u0629."','\u0626\u06d5\u0628\u0648 \u0628\u06d5\u06a9\u0631 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u0628\u0627\u0646\u06af\u06d5\u0634\u06d5\u06cc \u062e\u06c6\u0634\u06d5\u0648\u06cc\u0633\u062a\u06cc \u062e\u0648\u0627 \u0628\u06a9\u0627\u062a \u0648 \u0645\u0648\u0627\u0641\u0642\u06cc \u0646\u06d5\u0628\u06ce\u062a\u060c \u062f\u0627\u0648\u0627\u06a9\u0627\u0631\u06cc\u06cc\u06d5\u06a9\u06d5\u06cc \u067e\u0648\u0648\u0686\u06d5."','Abu Bakr said: "Who claims love of Allah but does not obey Him, his claim is false."'],t.w)
B.a8Z=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u062d\u0633\u0646 \u0627\u0644\u0628\u0635\u0631\u064a: "\u0645\u0627 \u0646\u0638\u0631\u062a \u0628\u0628\u0635\u0631\u064a \u0648\u0644\u0627 \u0646\u0637\u0642\u062a \u0628\u0644\u0633\u0627\u0646\u064a \u0648\u0644\u0627 \u0628\u0637\u0634\u062a \u0628\u064a\u062f\u064a \u062d\u062a\u0649 \u0623\u0646\u0638\u0631 \u0623\u0637\u0627\u0639\u0629 \u0644\u0644\u0647 \u0623\u0645 \u0645\u0639\u0635\u064a\u0629."','\u062d\u06d5\u0633\u06d5\u0646\u06cc \u0628\u06d5\u0633\u0631\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0647\u06cc\u0686 \u0646\u06d5\u0645 \u0628\u06cc\u0646\u06cc \u0648 \u0646\u06d5\u0645 \u06af\u0648\u062a \u0648 \u0646\u06d5\u0645 \u06a9\u0631\u062f \u062a\u0627 \u0633\u06d5\u06cc\u0631\u06cc \u0626\u06d5\u0648\u06d5 \u0646\u06d5\u06a9\u0631\u062f\u0628\u06ce\u062a \u06af\u0648\u06ce\u0695\u0627\u06cc\u06d5\u06b5\u06cc \u062e\u0648\u0627\u06cc\u06d5 \u06cc\u0627\u0646 \u0646\u0627\u0641\u06d5\u0631\u0645\u0627\u0646\u06cc."','Al-Hasan said: "I did not look, speak, or act without checking if it was obedience or sin."'],t.w)
B.a8C=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u0627\u0644\u062f\u0631\u062f\u0627\u0621: "\u0625\u0646\u064a \u0623\u062e\u0627\u0641 \u0623\u0646 \u064a\u0642\u0627\u0644 \u0644\u064a \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629: \u064a\u0627 \u0639\u0648\u064a\u0645\u0631 \u0647\u0644 \u0639\u0644\u0645\u062a\u061f \u0641\u0623\u0642\u0648\u0644: \u0646\u0639\u0645\u060c \u0641\u064a\u0642\u0627\u0644: \u0641\u0645\u0627\u0630\u0627 \u0639\u0645\u0644\u062a \u0641\u064a\u0645\u0627 \u0639\u0644\u0645\u062a\u061f"','\u0626\u06d5\u0628\u0648 \u062f\u06d5\u0631\u062f\u0627\u0621 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u062f\u06d5\u062a\u0631\u0633\u0645 \u0695\u06c6\u0698\u06cc \u062f\u0648\u0627\u0695\u06c6\u0698 \u067e\u06ce\u0645 \u0628\u06b5\u06ce\u0646: \u0626\u06d5\u06cc \u0639\u0648\u06d5\u06cc\u0645\u0631 \u0632\u0627\u0646\u06cc\u062a\u061f \u0628\u06b5\u06ce\u0645 \u0628\u06d5\u06b5\u06ce\u060c \u0628\u06b5\u06ce\u0646: \u0686\u06cc\u062a \u0628\u06d5\u0648 \u0632\u0627\u0646\u0633\u062a\u06d5\u0648\u06d5 \u06a9\u0631\u062f\u061f"','Abu Darda said: "I fear being asked: Did you know? Yes. What did you do with it?"'],t.w)
B.ack=new A.C(B.r,['\u0642\u0627\u0644 \u0639\u0645\u0631 \u0628\u0646 \u0639\u0628\u062f\u0627\u0644\u0639\u0632\u064a\u0632: "\u0645\u0646 \u0644\u0645 \u064a\u0643\u0646 \u063a\u0646\u0627\u0647 \u0641\u064a \u0646\u0641\u0633\u0647 \u0644\u0645 \u064a\u063a\u0646\u0647 \u0627\u0644\u0645\u0627\u0644."','\u0639\u0648\u0645\u06d5\u0631 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u062f\u06d5\u0648\u0644\u06d5\u0645\u06d5\u0646\u062f\u06cc \u0644\u06d5 \u0646\u06d5\u0641\u0633\u06cc \u0646\u06d5\u0628\u06ce\u062a\u060c \u0645\u0627\u06b5 \u062f\u06d5\u0648\u0644\u06d5\u0645\u06d5\u0646\u062f\u06cc \u0646\u0627\u06a9\u0627\u062a."','Umar said: "Who is not rich in soul, wealth will not enrich."'],t.w)
B.a9z=new A.C(B.r,['\u0642\u0627\u0644 \u0633\u0641\u064a\u0627\u0646 \u0627\u0644\u062b\u0648\u0631\u064a: "\u0645\u0627 \u0631\u0623\u064a\u062a \u0634\u064a\u0626\u0627\u064b \u0623\u0642\u0637\u0639 \u0644\u0638\u0647\u0631 \u0625\u0628\u0644\u064a\u0633 \u0645\u0646: \u0644\u0627 \u0625\u0644\u0647 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647."','\u0633\u0648\u0641\u06cc\u0627\u0646 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0647\u06cc\u0686\u0645 \u0646\u06d5\u0628\u06cc\u0646\u06cc\u0648\u06d5 \u067e\u0634\u062a\u06cc \u0634\u06d5\u06cc\u062a\u0627\u0646 \u0648\u06d5\u06a9 \u0644\u0627 \u0626\u06cc\u0644\u0627\u0647\u06d5 \u0626\u06cc\u0644\u0644\u06d5\u06b5\u06b5\u0627\u0647 \u0628\u0634\u06a9\u06ce\u0646\u06ce\u062a."','Sufyan said: "Nothing breaks the devil back like La ilaha illa Allah."'],t.w)
B.a8O=new A.C(B.r,['\u0642\u0627\u0644 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0628\u0646 \u0623\u062f\u0647\u0645: "\u0627\u0644\u0632\u0647\u062f \u062b\u0644\u0627\u062b\u0629 \u0623\u0635\u0646\u0627\u0641: \u0641\u0631\u0636 \u0648\u0641\u0636\u0644 \u0648\u0633\u0644\u0627\u0645\u0629."','\u0626\u06cc\u0628\u0631\u0627\u0647\u06cc\u0645 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0632\u0648\u0647\u062f \u0633\u06ce \u062c\u06c6\u0631\u06d5: \u0641\u06d5\u0631\u0632 \u0648 \u0641\u06d5\u0632\u06b5 \u0648 \u0633\u06d5\u0644\u0627\u0645\u06d5\u062a."','Ibrahim said: "Asceticism is three types: obligatory, virtuous, and safety."'],t.w)
B.abB=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u0641\u0636\u064a\u0644 \u0628\u0646 \u0639\u064a\u0627\u0636: "\u0644\u0648 \u0623\u0646 \u0623\u0647\u0644 \u0627\u0644\u0639\u0644\u0645 \u0623\u0643\u0631\u0645\u0648\u0627 \u0639\u0644\u0645\u0647\u0645 \u0648\u0635\u0627\u0646\u0648\u0647 \u0644\u0633\u0627\u062f\u0648\u0627 \u0628\u0647 \u0623\u0647\u0644 \u0627\u0644\u062f\u0646\u064a\u0627."','\u0641\u0648\u0632\u06d5\u06cc\u0644 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u06af\u06d5\u0631 \u0632\u0627\u0646\u0627\u06a9\u0627\u0646 \u0695\u06ce\u0632 \u0644\u06d5 \u0632\u0627\u0646\u0633\u062a\u06cc\u0627\u0646 \u0628\u06af\u0631\u0646 \u0648 \u0628\u06cc\u067e\u0627\u0631\u06ce\u0632\u0646\u060c \u0628\u06d5 \u0647\u06c6\u06a9\u06d5\u06cc \u0633\u06d5\u0631\u06c6\u06a9\u06cc \u062f\u0648\u0646\u06cc\u0627 \u062f\u06d5\u0628\u0646."','Fudayl said: "If scholars honored and preserved their knowledge, they would lead the world."'],t.w)
B.a8r=new A.C(B.r,['\u0642\u0627\u0644 \u0645\u0627\u0644\u0643 \u0628\u0646 \u062f\u064a\u0646\u0627\u0631: "\u0645\u0646 \u062a\u0639\u0644\u0645 \u0627\u0644\u0639\u0644\u0645 \u0644\u0644\u0639\u0645\u0644 \u0643\u0633\u0631\u0647 \u0627\u0644\u0639\u0644\u0645."','\u0645\u0627\u0644\u06a9 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u0632\u0627\u0646\u0633\u062a \u0628\u06c6 \u06a9\u0631\u062f\u0627\u0631 \u0641\u06ce\u0631 \u0628\u06ce\u062a\u060c \u0632\u0627\u0646\u0633\u062a \u062f\u06d5\u06cc\u0634\u06a9\u06ce\u0646\u06ce\u062a."','Malik said: "Who learns knowledge for action, knowledge humbles him."'],t.w)
B.a8j=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u0633\u0644\u064a\u0645\u0627\u0646 \u0627\u0644\u062f\u0627\u0631\u0627\u0646\u064a: "\u0631\u0628\u0645\u0627 \u064a\u0642\u0639 \u0641\u064a \u0642\u0644\u0628\u064a \u0627\u0644\u0646\u0643\u062a\u0629 \u0645\u0646 \u0646\u0643\u062a \u0627\u0644\u0642\u0648\u0645 \u0623\u064a\u0627\u0645\u0627\u064b \u0641\u0644\u0627 \u0623\u0642\u0628\u0644\u0647\u0627 \u0625\u0644\u0627 \u0628\u0634\u0627\u0647\u062f\u064a\u0646: \u0627\u0644\u0643\u062a\u0627\u0628 \u0648\u0627\u0644\u0633\u0646\u0629."','\u0626\u06d5\u0628\u0648 \u0633\u0648\u0644\u06d5\u06cc\u0645\u0627\u0646 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0647\u06d5\u0646\u062f\u06ce\u06a9 \u062c\u0627\u0631 \u0628\u06cc\u0631\u06c6\u06a9\u06d5\u06cc\u06d5\u06a9 \u0686\u06d5\u0646\u062f \u0695\u06c6\u0698 \u0644\u06d5 \u062f\u06b5\u0645\u062f\u0627 \u062f\u06d5\u0645\u06ce\u0646\u06ce\u062a\u06d5\u0648\u06d5\u060c \u0642\u0628\u0648\u0648\u06b5\u06cc \u0646\u0627\u06a9\u06d5\u0645 \u062c\u06af\u06d5 \u0628\u06d5 \u062f\u0648\u0648 \u0634\u0627\u0647\u06cc\u062f: \u06a9\u062a\u06ce\u0628 \u0648 \u0633\u0648\u0646\u0646\u06d5\u062a."','Abu Sulayman said: "I do not accept an idea except with two witnesses: Quran and Sunnah."'],t.w)
B.a8y=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u062c\u0646\u064a\u062f: "\u0637\u0631\u0642\u0646\u0627 \u0647\u0630\u0627 \u0645\u0642\u064a\u062f \u0628\u0627\u0644\u0643\u062a\u0627\u0628 \u0648\u0627\u0644\u0633\u0646\u0629."','\u062c\u0648\u0646\u06d5\u06cc\u062f \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0695\u06ce\u06af\u0627\u06cc \u0626\u06ce\u0645\u06d5 \u0628\u06d5\u0633\u062a\u0631\u0627\u0648\u06d5\u062a\u06d5\u0648\u06d5 \u0628\u06d5 \u06a9\u062a\u06ce\u0628 \u0648 \u0633\u0648\u0646\u0646\u06d5\u062a."','Junayd said: "Our path is bound by Quran and Sunnah."'],t.w)
B.aac=new A.C(B.r,['\u0642\u0627\u0644 \u064a\u062d\u064a\u0649 \u0628\u0646 \u0645\u0639\u0627\u0630: "\u0627\u0644\u062c\u0648\u0639 \u0646\u0648\u0631\u060c \u0648\u0627\u0644\u0634\u0628\u0639 \u0646\u0627\u0631."','\u06cc\u06d5\u062d\u06cc\u0627 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0628\u0631\u0633\u06cc\u06ce\u062a\u06cc \u0695\u0648\u0646\u0627\u06a9\u06cc\u06cc\u06d5\u060c \u062a\u06ce\u0631\u0628\u0648\u0648\u0646 \u0626\u0627\u06af\u0631\u06d5."','Yahya said: "Hunger is light, satiety is fire."'],t.w)
B.ab1=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0627\u0644\u0642\u064a\u0645: "\u0645\u0646 \u0623\u0631\u0627\u062f \u0639\u0644\u0648 \u0627\u0644\u0647\u0645\u0629 \u0641\u0644\u064a\u062d\u0631\u0635 \u0639\u0644\u0649 \u062b\u0644\u0627\u062b: \u0627\u0644\u0635\u062f\u0642 \u0648\u0627\u0644\u0625\u062e\u0644\u0627\u0635 \u0648\u0645\u062c\u0627\u0647\u062f\u0629 \u0627\u0644\u0646\u0641\u0633."','\u0627\u0628\u0646 \u0642\u06d5\u06cc\u0645 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u0648\u06cc\u0633\u062a\u06cc \u0628\u06d5\u0631\u0632 \u0628\u0648\u06ce\u062a\u060c \u0628\u0627 \u062d\u06d5\u0631\u06cc\u0633 \u0628\u06ce\u062a \u0644\u06d5\u0633\u06d5\u0631 \u0633\u06ce \u0634\u062a: \u0695\u0627\u0633\u062a\u06af\u06c6\u06cc\u06cc \u0648 \u062f\u06b5\u0633\u06c6\u0632\u06cc \u0648 \u062a\u06ce\u06a9\u06c6\u0634\u0627\u0646\u06cc \u0646\u06d5\u0641\u0633."','Ibn al-Qayyim said: "Who wants high aspiration, let him focus on truth, sincerity, and self-struggle."'],t.w)
B.a8t=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u0634\u0627\u0641\u0639\u064a: "\u0645\u0627 \u062c\u0627\u062f\u0644\u062a \u0623\u062d\u062f\u0627\u064b \u0625\u0644\u0627 \u062a\u0645\u0646\u064a\u062a \u0623\u0646 \u064a\u0638\u0647\u0631 \u0627\u0644\u0644\u0647 \u0627\u0644\u062d\u0642 \u0639\u0644\u0649 \u0644\u0633\u0627\u0646\u0647."','\u0634\u0627\u0641\u0639\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0644\u06d5\u06af\u06d5\u06b5 \u0647\u06cc\u0686 \u06a9\u06d5\u0633\u06ce\u06a9 \u0645\u0628\u0627\u062d\u06d5\u0633\u06d5\u0645 \u0646\u06d5\u06a9\u0631\u062f\u0648\u0648\u06d5 \u062c\u06af\u06d5 \u0644\u06d5\u0648\u06d5\u06cc \u0647\u06cc\u0648\u0627\u0645 \u0628\u0628\u06ce\u062a \u062e\u0648\u0627 \u0695\u0627\u0633\u062a\u06cc\u06cc\u06d5\u06a9\u06d5 \u0644\u06d5\u0633\u06d5\u0631 \u0632\u0645\u0627\u0646\u06d5\u06a9\u06d5\u06cc \u062f\u06d5\u0631\u0628\u062e\u0627\u062a."','Al-Shafi said: "I never debated anyone without hoping truth would come through them."'],t.w)
B.a9U=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u062d\u0645\u062f \u0628\u0646 \u062d\u0646\u0628\u0644: "\u0645\u0627 \u0643\u062a\u0628\u062a \u062d\u062f\u064a\u062b\u0627\u064b \u0625\u0644\u0627 \u0648\u0642\u062f \u0639\u0645\u0644\u062a \u0628\u0647."','\u0626\u06d5\u062d\u0645\u06d5\u062f \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0647\u06cc\u0686 \u062d\u06d5\u062f\u06cc\u0633\u06ce\u06a9\u0645 \u0646\u06d5\u0646\u0648\u0648\u0633\u06cc\u0648\u06d5 \u062c\u06af\u06d5 \u0644\u06d5\u0648\u06d5\u06cc \u06a9\u0631\u062f\u0628\u06ce\u062a\u0645 \u067e\u06ce\u06cc."','Ahmad said: "I never wrote a hadith without acting upon it."'],t.w)
B.a92=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u062d\u0646\u064a\u0641\u0629: "\u0646\u062d\u0646 \u0642\u0648\u0645 \u0646\u0642\u0648\u0644 \u0628\u0627\u0644\u0631\u0623\u064a \u0641\u0645\u0646 \u062c\u0627\u0621\u0646\u0627 \u0628\u0623\u062d\u0633\u0646 \u0645\u0646\u0647 \u0642\u0628\u0644\u0646\u0627\u0647."','\u0626\u06d5\u0628\u0648 \u062d\u06d5\u0646\u06cc\u0641\u06d5 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06ce\u0645\u06d5 \u0628\u06d5 \u0695\u0627\u06cc \u062e\u06c6\u0645\u0627\u0646 \u0642\u0633\u06d5 \u062f\u06d5\u06a9\u06d5\u06cc\u0646\u060c \u0626\u06d5\u0648\u06d5\u06cc \u0628\u0627\u0634\u062a\u0631\u06cc \u0647\u06ce\u0646\u0627 \u0642\u0628\u0648\u0648\u06b5\u06cc \u062f\u06d5\u06a9\u06d5\u06cc\u0646."','Abu Hanifa said: "We speak by opinion; whoever brings better, we accept."'],t.w)
B.ac0=new A.C(B.r,['\u0642\u0627\u0644 \u0645\u0627\u0644\u0643: "\u0643\u0644 \u064a\u0624\u062e\u0630 \u0645\u0646 \u0642\u0648\u0644\u0647 \u0648\u064a\u0631\u062f \u0625\u0644\u0627 \u0635\u0627\u062d\u0628 \u0647\u0630\u0627 \u0627\u0644\u0642\u0628\u0631."','\u0626\u06cc\u0645\u0627\u0645 \u0645\u0627\u0644\u06a9 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0642\u0633\u06d5\u06cc \u0647\u06d5\u0645\u0648\u0648 \u06a9\u06d5\u0633\u06ce\u06a9 \u0648\u06d5\u0631\u062f\u06d5\u06af\u06cc\u0631\u06ce\u062a \u0648 \u0695\u06d5\u062a \u062f\u06d5\u06a9\u0631\u06ce\u062a\u06d5\u0648\u06d5 \u062c\u06af\u06d5 \u0644\u06d5 \u062e\u0627\u0648\u06d5\u0646\u06cc \u0626\u06d5\u0645 \u06af\u06c6\u0695\u06d5."','Malik said: "Everyone opinion can be taken or rejected except the Prophet."'],t.w)
B.aaU=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u062a\u064a\u0645\u064a\u0629: "\u0627\u0644\u0642\u0644\u0628 \u0644\u0627 \u064a\u0635\u0644\u062d \u0648\u0644\u0627 \u064a\u0641\u0644\u062d \u0648\u0644\u0627 \u064a\u0644\u062a\u0630 \u0625\u0644\u0627 \u0628\u0639\u0628\u0627\u062f\u0629 \u0627\u0644\u0644\u0647."','\u0627\u0628\u0646 \u062a\u06d5\u06cc\u0645\u06cc\u06d5 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u062f\u06b5 \u0686\u0627\u06a9 \u0646\u0627\u0628\u06ce\u062a \u0648 \u0633\u06d5\u0631\u06a9\u06d5\u0648\u062a\u0648\u0648 \u0646\u0627\u0628\u06ce\u062a \u0648 \u062a\u0627\u0645 \u0646\u0627\u0628\u06ce\u062a \u062c\u06af\u06d5 \u0628\u06d5 \u067e\u06d5\u0631\u0633\u062a\u0646\u06cc \u062e\u0648\u0627."','Ibn Taymiyyah said: "The heart is only good, successful, and pleased by worshipping Allah."'],t.w)
B.aax=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0631\u062c\u0628: "\u0627\u0644\u0639\u0644\u0645 \u0627\u0644\u0646\u0627\u0641\u0639 \u0645\u0627 \u0639\u064f\u0631\u0641 \u0628\u0647 \u0627\u0644\u0631\u0628."','\u0627\u0628\u0646 \u0695\u06d5\u062c\u06d5\u0628 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0632\u0627\u0646\u0633\u062a\u06cc \u0633\u0648\u0648\u062f\u0645\u06d5\u0646\u062f \u0626\u06d5\u0648\u06d5\u06cc\u06d5 \u06a9\u06d5 \u067e\u06d5\u0631\u0648\u06d5\u0631\u062f\u06af\u0627\u0631 \u067e\u06ce \u0628\u0646\u0627\u0633\u0631\u06ce\u062a."','Ibn Rajab said: "Beneficial knowledge is that by which the Lord is known."'],t.w)
B.aa7=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0627\u0644\u062c\u0648\u0632\u064a: "\u0645\u0646 \u0639\u0644\u0627\u0645\u0629 \u0627\u0644\u0645\u0642\u062a \u0623\u0646 \u062a\u0631\u0649 \u062a\u0642\u0635\u064a\u0631\u0643 \u0648\u0644\u0627 \u062a\u062a\u062f\u0627\u0631\u0643."','\u0627\u0628\u0646 \u062c\u06d5\u0648\u0632\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0646\u06cc\u0634\u0627\u0646\u06d5\u06cc\u06d5\u06a9\u06cc \u0695\u0642 \u0626\u06d5\u0648\u06d5\u06cc\u06d5 \u06a9\u06d5\u0645\u0648\u06a9\u0648\u0695\u06cc\u06cc\u06d5\u06a9\u06d5\u062a \u0628\u0628\u06cc\u0646\u06cc\u062a \u0648 \u0686\u0627\u0631\u06d5\u0633\u06d5\u0631\u06cc \u0646\u06d5\u06a9\u06d5\u06cc\u062a."','Ibn al-Jawzi said: "A sign of being hated is seeing your shortcomings and not fixing them."'],t.w)
B.a8S=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u063a\u0632\u0627\u0644\u064a: "\u0644\u064a\u0633 \u0644\u0644\u0625\u0646\u0633\u0627\u0646 \u0625\u0644\u0627 \u0645\u0627 \u0633\u0639\u0649."','\u063a\u06d5\u0632\u0627\u0644\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0645\u0631\u06c6\u06a4 \u062a\u06d5\u0646\u0647\u0627 \u0626\u06d5\u0648\u06d5\u06cc \u0647\u06d5\u06cc\u06d5 \u06a9\u06d5 \u062a\u06ce\u06cc\u06a9\u06c6\u0634\u0627."','Al-Ghazali said: "Man has only what he strived for."'],t.w)
B.aa8=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u0646\u0648\u0648\u064a: "\u0625\u064a\u0627\u0643 \u0648\u0645\u0635\u0627\u062d\u0628\u0629 \u0627\u0644\u0643\u0633\u0627\u0644\u0649\u060c \u0641\u0625\u0646\u0647\u0627 \u062a\u0636\u0631\u0643 \u0645\u0646 \u062d\u064a\u062b \u0644\u0627 \u062a\u0634\u0639\u0631."','\u0646\u06d5\u0648\u06d5\u0648\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0644\u06d5 \u0647\u0627\u0648\u0695\u06ce\u06cc\u06d5\u062a\u06cc \u062a\u06d5\u0645\u06d5\u06b5\u06d5\u06a9\u0627\u0646 \u0628\u067e\u06d5\u0631\u0647\u06ce\u0632\u06d5\u060c \u0632\u06cc\u0627\u0646\u062a \u067e\u06ce \u062f\u06d5\u06af\u06d5\u06cc\u06d5\u0646\u0646 \u0628\u06ce \u0626\u06d5\u0648\u06d5\u06cc \u0647\u06d5\u0633\u062a \u067e\u06ce \u0628\u06a9\u06d5\u06cc\u062a."','Al-Nawawi said: "Avoid lazy companions; they harm you without you realizing."'],t.w)
B.aaE=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0643\u062b\u064a\u0631: "\u0645\u0646 \u0623\u0643\u062b\u0631 \u0645\u0646 \u0630\u0643\u0631 \u0627\u0644\u0645\u0648\u062a \u0623\u064f\u0643\u0631\u0645 \u0628\u062b\u0644\u0627\u062b: \u062a\u0639\u062c\u064a\u0644 \u0627\u0644\u062a\u0648\u0628\u0629 \u0648\u0642\u0646\u0627\u0639\u0629 \u0627\u0644\u0642\u0644\u0628 \u0648\u0646\u0634\u0627\u0637 \u0627\u0644\u0639\u0628\u0627\u062f\u0629."','\u0627\u0628\u0646 \u06a9\u06d5\u0633\u06cc\u0631 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u0632\u06c6\u0631 \u06cc\u0627\u062f\u06cc \u0645\u06d5\u0631\u06af \u0628\u06a9\u0627\u062a \u0633\u06ce \u0634\u062a\u06cc \u067e\u06ce \u062f\u06d5\u0628\u06d5\u062e\u0634\u0631\u06ce\u062a: \u0628\u06d5\u067e\u06d5\u0644\u06d5\u06cc\u06cc \u062a\u06d5\u0648\u0628\u06d5\u060c \u0642\u06d5\u0646\u0627\u0639\u06d5\u062a\u06cc \u062f\u06b5\u060c \u0686\u0627\u0644\u0627\u06a9\u06cc \u0639\u06cc\u0628\u0627\u062f\u06d5."','Ibn Kathir said: "Who remembers death much is honored with three: quick repentance, contentment, and active worship."'],t.w)
B.aco=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u0630\u0647\u0628\u064a: "\u0625\u0630\u0627 \u0631\u0623\u064a\u062a \u0627\u0644\u0639\u0627\u0644\u0645 \u0644\u0627 \u064a\u062a\u0648\u0627\u0636\u0639 \u0641\u0627\u0639\u0644\u0645 \u0623\u0646\u0647 \u0642\u062f \u0627\u0628\u062a\u0644\u064a."','\u0632\u06d5\u0647\u06d5\u0628\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u06af\u06d5\u0631 \u0632\u0627\u0646\u0627 \u0646\u06d5\u06cc\u0628\u06cc\u0646\u06cc \u062e\u06c6\u06cc \u0628\u0686\u0648\u0648\u06a9 \u0628\u06a9\u0627\u062a\u060c \u0628\u0632\u0627\u0646\u06d5 \u062a\u0648\u0648\u0634\u06cc \u0628\u06d5\u06b5\u0627 \u0628\u0648\u0648\u06d5."','Al-Dhahabi said: "If you see a scholar not humble, know he is afflicted."'],t.w)
B.a8H=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0628\u0627\u0632: "\u0627\u0644\u0639\u0644\u0645 \u0628\u0627\u0644\u0644\u0647 \u0623\u0634\u0631\u0641 \u0627\u0644\u0639\u0644\u0648\u0645."','\u0627\u0628\u0646 \u0628\u0627\u0632 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0632\u0627\u0646\u0633\u062a \u0628\u06d5 \u062e\u0648\u0627 \u0634\u06d5\u0631\u06d5\u0641\u062a\u0631\u06cc\u0646 \u0632\u0627\u0646\u0633\u062a\u06d5\u06a9\u0627\u0646\u06d5."','Ibn Baz said: "Knowledge of Allah is the noblest knowledge."'],t.w)
B.abj=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0639\u062b\u064a\u0645\u064a\u0646: "\u0627\u0644\u062a\u0648\u062d\u064a\u062f \u0647\u0648 \u0623\u0648\u0644 \u0627\u0644\u062f\u064a\u0646 \u0648\u0622\u062e\u0631\u0647 \u0648\u0638\u0627\u0647\u0631\u0647 \u0648\u0628\u0627\u0637\u0646\u0647."','\u0627\u0628\u0646 \u0639\u0648\u0633\u06d5\u06cc\u0645\u06cc\u0646 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u062a\u06d5\u0648\u062d\u06cc\u062f \u06cc\u06d5\u06a9\u06d5\u0645 \u0648 \u06a9\u06c6\u062a\u0627\u06cc \u0626\u0627\u06cc\u06cc\u0646\u06d5 \u0648 \u062f\u06d5\u0631\u06d5\u06a9\u06cc \u0648 \u0646\u0627\u0648\u06d5\u06a9\u06cc\u06cc\u06d5\u06a9\u06d5\u06cc\u06d5."','Ibn Uthaymeen said: "Tawhid is the first, last, outer, and inner of religion."'],t.w)
B.abh=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u0623\u0644\u0628\u0627\u0646\u064a: "\u0627\u0644\u0627\u0639\u062a\u0635\u0627\u0645 \u0628\u0627\u0644\u0643\u062a\u0627\u0628 \u0648\u0627\u0644\u0633\u0646\u0629 \u0647\u0648 \u0627\u0644\u0639\u0631\u0648\u0629 \u0627\u0644\u0648\u062b\u0642\u0649."','\u0626\u06d5\u0644\u0628\u0627\u0646\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u067e\u06d5\u0646\u0627\u0628\u0631\u062f\u0646 \u0628\u06c6 \u06a9\u062a\u06ce\u0628 \u0648 \u0633\u0648\u0646\u0646\u06d5\u062a \u062f\u06d5\u0633\u062a\u06af\u06cc\u0631\u06d5 \u0628\u06d5\u0647\u06ce\u0632\u06d5\u06a9\u06d5\u06cc\u06d5."','Al-Albani said: "Holding to Quran and Sunnah is the firmest handhold."'],t.w)
B.abp=new A.C(B.r,['\u0642\u0627\u0644 \u0639\u0645\u0631 \u0628\u0646 \u0627\u0644\u062e\u0637\u0627\u0628: "\u0646\u062d\u0646 \u0642\u0648\u0645 \u0623\u0639\u0632\u0646\u0627 \u0627\u0644\u0644\u0647 \u0628\u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0641\u0645\u0647\u0645\u0627 \u0627\u0628\u062a\u063a\u064a\u0646\u0627 \u0627\u0644\u0639\u0632\u0629 \u0628\u063a\u064a\u0631\u0647 \u0623\u0630\u0644\u0646\u0627 \u0627\u0644\u0644\u0647."','\u0639\u0648\u0645\u06d5\u0631 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06ce\u0645\u06d5 \u06af\u06d5\u0644\u06ce\u06a9\u06cc\u0646 \u062e\u0648\u0627 \u0628\u06d5 \u0626\u06cc\u0633\u0644\u0627\u0645 \u0633\u06d5\u0631\u0628\u06d5\u0631\u0632\u0645\u0627\u0646 \u06a9\u0631\u062f\u0648\u0648\u06d5\u060c \u0647\u06d5\u0631 \u06a9\u0627\u062a\u06ce\u06a9 \u062c\u06af\u06d5 \u0644\u06d5\u0648\u06d5 \u0633\u06d5\u0631\u0628\u06d5\u0631\u0632\u06cc \u0628\u0648\u06ce\u06cc\u0646 \u062e\u0648\u0627 \u062e\u0648\u0627\u0631\u0645\u0627\u0646 \u062f\u06d5\u06a9\u0627\u062a."','Umar said: "We are a people Allah honored by Islam; if we seek honor elsewhere, He humiliates us."'],t.w)
B.ac2=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u0628\u0643\u0631: "\u0644\u064a\u0633 \u0627\u0644\u062e\u064a\u0627\u0631 \u0641\u064a \u0632\u0645\u0646 \u0627\u0644\u0641\u062a\u0646\u0629 \u062e\u064a\u0631\u0627\u064b\u060c \u0648\u0644\u0643\u0646 \u062a\u0631\u0643 \u0627\u0644\u0641\u062a\u0646\u0629 \u062e\u064a\u0631."','\u0626\u06d5\u0628\u0648 \u0628\u06d5\u06a9\u0631 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0644\u06d5 \u06a9\u0627\u062a\u06cc \u0641\u06cc\u062a\u0646\u06d5\u062f\u0627 \u0647\u06d5\u06b5\u0628\u0698\u0627\u0631\u062f\u0646\u06cc \u0628\u0627\u0634 \u0686\u0627\u06a9 \u0646\u06cc\u06cc\u06d5\u060c \u0628\u06d5\u06b5\u0627\u0645 \u0648\u0627\u0632\u0647\u06ce\u0646\u0627\u0646 \u0644\u06d5 \u0641\u06cc\u062a\u0646\u06d5 \u0686\u0627\u06a9\u06d5."','Abu Bakr said: "In times of strife, choosing good is not good; leaving strife is."'],t.w)
B.abq=new A.C(B.r,['\u0642\u0627\u0644 \u0639\u0644\u064a: "\u0644\u0633\u0627\u0646\u0643 \u0623\u0633\u062f\u060c \u0625\u0646 \u0623\u0637\u0644\u0642\u062a\u0647 \u0623\u0643\u0644\u0643."','\u0639\u06d5\u0644\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0632\u0645\u0627\u0646\u062a \u0634\u06ce\u0631\u06d5\u060c \u0626\u06d5\u06af\u06d5\u0631 \u0628\u06d5\u0631\u062f\u06d5\u06cc\u062f\u0627 \u062f\u06d5\u062a\u062e\u0648\u0627\u062a."','Ali said: "Your tongue is a lion; if you release it, it devours you."'],t.w)
B.a8P=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0639\u0628\u0627\u0633: "\u0643\u0644 \u0645\u0627 \u0641\u064a \u0627\u0644\u0642\u0631\u0622\u0646 \u0645\u0646 \u0623\u0645\u0631 \u0641\u0647\u0648 \u0644\u0644\u0648\u062c\u0648\u0628."','\u0627\u0628\u0646 \u0639\u06d5\u0628\u0627\u0633 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0647\u06d5\u0645\u0648\u0648 \u0626\u06d5\u0648\u06d5\u06cc \u0644\u06d5 \u0642\u0648\u0631\u0626\u0627\u0646 \u0641\u06d5\u0631\u0645\u0627\u0646 \u0628\u0648\u0648 \u0648\u0627\u062c\u0628\u06d5."','Ibn Abbas said: "Every command in Quran is obligatory."'],t.w)
B.abH=new A.C(B.r,['\u0642\u0627\u0644 \u0633\u0639\u064a\u062f \u0628\u0646 \u0627\u0644\u0645\u0633\u064a\u0628: "\u0644\u0627 \u062e\u064a\u0631 \u0641\u064a\u0645\u0646 \u0644\u0627 \u064a\u062d\u0628 \u0627\u0644\u0639\u0644\u0645."','\u0633\u06d5\u0639\u06cc\u062f \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0647\u06cc\u0686 \u0686\u0627\u06a9\u06d5 \u0646\u06cc\u06cc\u06d5 \u0644\u06d5\u0648\u06d5\u06cc \u062d\u06d5\u0632\u06cc \u0644\u06d5 \u0632\u0627\u0646\u0633\u062a \u0646\u06d5\u0628\u06ce\u062a."','Said said: "There is no good in who does not love knowledge."'],t.w)
B.abl=new A.C(B.r,['\u0642\u0627\u0644 \u0645\u062d\u0645\u062f \u0628\u0646 \u0633\u064a\u0631\u064a\u0646: "\u0625\u0646 \u0647\u0630\u0627 \u0627\u0644\u0639\u0644\u0645 \u062f\u064a\u0646 \u0641\u0627\u0646\u0638\u0631\u0648\u0627 \u0639\u0645\u0646 \u062a\u0623\u062e\u0630\u0648\u0646 \u062f\u064a\u0646\u0643\u0645."','\u0627\u0628\u0646 \u0633\u06cc\u0631\u06cc\u0646 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0645 \u0632\u0627\u0646\u0633\u062a\u06d5 \u0626\u0627\u06cc\u06cc\u0646\u06d5\u060c \u062a\u06d5\u0645\u0627\u0634\u0627 \u0628\u06a9\u06d5\u0646 \u0644\u06d5\u0644\u0627\u06cc \u06a9\u06ce \u0626\u0627\u06cc\u06cc\u0646\u06d5\u06a9\u06d5\u062a\u0627\u0646 \u0648\u06d5\u0631\u062f\u06d5\u06af\u0631\u0646."','Ibn Sirin said: "This knowledge is religion; look from whom you take your religion."'],t.w)
B.aaX=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0627\u0644\u0645\u0628\u0627\u0631\u0643: "\u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0628\u062e\u0648\u0627\u062a\u064a\u0645 \u0623\u0639\u0645\u0627\u0644\u0647."','\u0627\u0628\u0646 \u0645\u0648\u0628\u0627\u0631\u06d5\u06a9 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0645\u0631\u06c6\u06a4 \u0628\u06d5 \u06a9\u06c6\u062a\u0627\u06cc\u06cc \u06a9\u0631\u062f\u0627\u0631\u06d5\u06a9\u0627\u0646\u06cc\u06cc\u06d5\u0648\u06d5\u06cc\u06d5."','Ibn Mubarak said: "A person is judged by his final deeds."'],t.w)
B.a9y=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u0623\u0648\u0632\u0627\u0639\u064a: "\u0627\u0644\u0639\u0644\u0645 \u0645\u0627 \u062c\u0627\u0621 \u0639\u0646 \u0623\u0635\u062d\u0627\u0628 \u0645\u062d\u0645\u062f."','\u0626\u06d5\u0648\u0632\u0627\u0639\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0632\u0627\u0646\u0633\u062a \u0626\u06d5\u0648\u06d5\u06cc\u06d5 \u0644\u06d5 \u0647\u0627\u0648\u06d5\u06b5\u06d5\u06a9\u0627\u0646\u06cc \u0645\u062d\u06d5\u0645\u0645\u06d5\u062f\u06d5\u0648\u06d5 \u0647\u0627\u062a\u0648\u0648\u06d5."','Al-Awzai said: "Knowledge is what came from the companions of Muhammad."'],t.w)
B.aa5=new A.C(B.r,['\u0642\u0627\u0644 \u0633\u0641\u064a\u0627\u0646 \u0628\u0646 \u0639\u064a\u064a\u0646\u0629: "\u0627\u0644\u0632\u0647\u062f \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0642\u0635\u0631 \u0627\u0644\u0623\u0645\u0644."','\u0633\u0648\u0641\u06cc\u0627\u0646\u06cc \u06a9\u0648\u0695\u06cc \u0639\u0648\u06cc\u06d5\u06cc\u0646\u06d5 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0632\u0648\u0647\u062f \u0644\u06d5 \u062f\u0648\u0646\u06cc\u0627 \u06a9\u0648\u0631\u062a\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc \u0626\u0648\u0645\u06ce\u062f\u06d5."','Sufyan said: "Asceticism is shortening worldly hopes."'],t.w)
B.a9g=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u0644\u064a\u062b \u0628\u0646 \u0633\u0639\u062f: "\u0623\u062e\u0634\u0649 \u0639\u0644\u0649 \u0637\u0627\u0644\u0628 \u0627\u0644\u0639\u0644\u0645 \u0627\u0644\u0646\u064a\u0629."','\u0644\u06d5\u06cc\u0633 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0644\u06d5\u0633\u06d5\u0631 \u062e\u0648\u06ce\u0646\u062f\u06a9\u0627\u0631\u06cc \u0632\u0627\u0646\u0633\u062a \u0644\u06d5 \u0646\u06cc\u06d5\u062a \u062f\u06d5\u062a\u0631\u0633\u0645."','Al-Layth said: "I fear for the knowledge seeker about intention."'],t.w)
B.aa3=new A.C(B.r,['\u0642\u0627\u0644 \u0648\u0643\u064a\u0639 \u0628\u0646 \u0627\u0644\u062c\u0631\u0627\u062d: "\u0625\u0646 \u0647\u0630\u0627 \u0627\u0644\u0639\u0644\u0645 \u0644\u0627 \u064a\u0646\u0627\u0644 \u0628\u0631\u0627\u062d\u0629 \u0627\u0644\u062c\u0633\u0645."','\u0648\u06d5\u06a9\u06cc\u0639 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0645 \u0632\u0627\u0646\u0633\u062a\u06d5 \u0628\u06d5 \u0626\u0627\u0633\u0648\u0648\u062f\u06d5\u06cc\u06cc \u062c\u06d5\u0633\u062a\u06d5 \u0628\u06d5\u062f\u06d5\u0633\u062a \u0646\u0627\u0647\u06ce\u0646\u0631\u06ce\u062a."','Waki said: "This knowledge is not obtained with bodily comfort."'],t.w)
B.ac3=new A.C(B.r,['\u0642\u0627\u0644 \u0639\u0628\u062f\u0627\u0644\u0631\u062d\u0645\u0646 \u0628\u0646 \u0645\u0647\u062f\u064a: "\u0644\u0648 \u0642\u064a\u0644 \u0644\u0645\u0627\u0644\u0643: \u0645\u0627 \u0623\u0641\u0636\u0644 \u0627\u0644\u0623\u0639\u0645\u0627\u0644\u061f \u0644\u0642\u0627\u0644: \u0627\u0644\u0635\u0644\u0627\u0629 \u0641\u064a \u0623\u0648\u0644 \u0648\u0642\u062a\u0647\u0627."','\u0639\u06d5\u0628\u062f\u0648\u0695\u062d\u0645\u0627\u0646 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u06af\u06d5\u0631 \u0644\u06d5 \u0645\u0627\u0644\u06a9 \u062f\u06d5\u067e\u0631\u0633\u06cc\u0646: \u0628\u0627\u0634\u062a\u0631\u06cc\u0646 \u06a9\u0631\u062f\u0627\u0631 \u0686\u06cc\u06cc\u06d5\u061f \u062f\u06d5\u06cc\u0641\u06d5\u0631\u0645\u0648\u0648: \u0646\u0648\u06ce\u0698 \u0644\u06d5 \u06cc\u06d5\u06a9\u06d5\u0645 \u06a9\u0627\u062a\u06d5\u06a9\u06d5\u06cc\u062f\u0627."','Abdurrahman said: "If Malik was asked the best deed, he would say: prayer at its earliest time."'],t.w)
B.a9T=new A.C(B.r,['\u0642\u0627\u0644 \u064a\u062d\u064a\u0649 \u0628\u0646 \u0633\u0639\u064a\u062f: "\u0645\u0627 \u0631\u0623\u064a\u062a \u0627\u0644\u0635\u0627\u0644\u062d\u064a\u0646 \u0641\u064a \u0634\u064a\u0621 \u0623\u0643\u0630\u0628 \u0645\u0646\u0647\u0645 \u0641\u064a \u0627\u0644\u062d\u062f\u064a\u062b."','\u06cc\u06d5\u062d\u06cc\u0627 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0686\u0627\u06a9\u06d5\u06a9\u0627\u0646\u0645 \u0644\u06d5 \u0647\u06cc\u0686 \u0634\u062a\u06ce\u06a9 \u0632\u06cc\u0627\u062a\u0631 \u0644\u06d5 \u062d\u06d5\u062f\u06cc\u0633 \u0646\u06d5\u0628\u06cc\u0646\u06cc \u062f\u0631\u06c6 \u0628\u06a9\u06d5\u0646."','Yahya said: "I have not seen righteous people lie more than in hadith narration."'],t.w)
B.abO=new A.C(B.r,['\u0642\u0627\u0644 \u0634\u0639\u0628\u0629: "\u0625\u0630\u0627 \u062d\u062f\u062b\u062a \u0645\u0646 \u062d\u0641\u0638\u064a \u0623\u062e\u0637\u0623\u062a\u060c \u0648\u0625\u0630\u0627 \u062d\u062f\u062b\u062a \u0645\u0646 \u0643\u062a\u0627\u0628\u064a \u0623\u0635\u0628\u062a."','\u0634\u0648\u0639\u0628\u06d5 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u06a9\u0627\u062a\u06ce\u06a9 \u0644\u06d5 \u062d\u06cc\u0641\u0632 \u062f\u06d5\u06af\u06ce\u0695\u0645\u06d5\u0648\u06d5 \u0647\u06d5\u06b5\u06d5 \u062f\u06d5\u06a9\u06d5\u0645\u060c \u06a9\u0627\u062a\u06ce\u06a9 \u0644\u06d5 \u06a9\u062a\u06ce\u0628 \u062f\u06d5\u06af\u06ce\u0695\u0645\u06d5\u0648\u06d5 \u0695\u0627\u0633\u062a\u06cc \u062f\u06d5\u06a9\u06d5\u0645."','Shuba said: "When I narrate from memory I err, from book I am correct."'],t.w)
B.abD=new A.C(B.r,['\u0642\u0627\u0644 \u062d\u0645\u0627\u062f \u0628\u0646 \u0632\u064a\u062f: "\u0623\u062f\u0631\u0643\u062a \u0623\u064a\u0648\u0628 \u0648\u064a\u0648\u0646\u0633 \u0648\u0627\u0628\u0646 \u0639\u0648\u0646 \u0648\u0647\u0645 \u0628\u0627\u0644\u0633\u0646\u0629 \u064a\u0643\u062a\u0641\u0648\u0646."','\u062d\u06d5\u0645\u0645\u0627\u062f \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u06cc\u0648\u0628 \u0648 \u06cc\u0648\u0646\u0633 \u0648 \u0627\u0628\u0646 \u0639\u06d5\u0648\u0646\u0645 \u0628\u06d5\u0632\u0627\u0646\u062f \u0648 \u0628\u06d5 \u0633\u0648\u0646\u0646\u06d5\u062a \u0642\u06d5\u0646\u0627\u0639\u06d5\u062a \u062f\u06d5\u06a9\u0631\u062f\u0646."','Hammad said: "I met Ayyub, Yunus, and Ibn Awn, and they were content with Sunnah."'],t.w)
B.aaD=new A.C(B.r,['\u0642\u0627\u0644 \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0628\u0646 \u0648\u0647\u0628: "\u0645\u0627 \u062a\u0639\u0644\u0645\u062a \u0645\u0646 \u0623\u062f\u0628 \u0645\u0627\u0644\u0643 \u0623\u0643\u062b\u0631 \u0645\u0645\u0627 \u062a\u0639\u0644\u0645\u062a \u0645\u0646 \u0639\u0644\u0645\u0647."','\u0639\u06d5\u0628\u062f\u0648\u0644\u0644\u0627\u06cc \u06a9\u0648\u0695\u06cc \u0648\u06d5\u0647\u0628 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u0644\u06d5 \u0626\u06d5\u062f\u06d5\u0628\u06cc \u0645\u0627\u0644\u06a9 \u0641\u06ce\u0631\u0628\u0648\u0648\u0645 \u0632\u06cc\u0627\u062a\u0631\u06d5 \u0644\u06d5 \u0632\u0627\u0646\u0633\u062a\u06d5\u06a9\u06d5\u06cc."','Abdullah said: "I learned more from Malik manners than his knowledge."'],t.w)
B.a8D=new A.C(B.r,['\u0642\u0627\u0644 \u0639\u0628\u062f\u0627\u0644\u0631\u0632\u0627\u0642: "\u0623\u0641\u0636\u0649 \u0644\u064a \u0645\u0639\u0645\u0631 \u0628\u0623\u0634\u064a\u0627\u0621 \u0644\u0645 \u064a\u0641\u0636 \u0628\u0647\u0627 \u0644\u0623\u062d\u062f."','\u0639\u06d5\u0628\u062f\u0648\u0695\u06d5\u0632\u0632\u0627\u0642 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0645\u06d5\u0639\u0645\u06d5\u0631 \u0634\u062a\u06cc \u067e\u06ce \u06af\u0648\u062a\u0645 \u06a9\u06d5 \u0628\u06d5 \u0647\u06cc\u0686 \u06a9\u06d5\u0633\u06cc \u0646\u06d5\u06cc\u06af\u0648\u062a\u0648\u0648\u06d5."','Abdurrazzaq said: "Mamar told me things he told no one else."'],t.w)
B.acg=new A.C(B.r,['\u0642\u0627\u0644 \u0645\u0639\u0645\u0631 \u0628\u0646 \u0631\u0627\u0634\u062f: "\u0631\u062d\u0644 \u0627\u0644\u0632\u0647\u0631\u064a \u0625\u0644\u0649 \u0627\u0644\u0634\u0627\u0645 \u0648\u0647\u0648 \u0623\u0639\u0644\u0645 \u0627\u0644\u0646\u0627\u0633."','\u0645\u06d5\u0639\u0645\u06d5\u0631 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0632\u0648\u0647\u0631\u06cc \u06af\u06d5\u0695\u0627 \u0628\u06c6 \u0634\u0627\u0645 \u0648 \u0626\u06d5\u0648 \u0632\u0627\u0646\u0627\u062a\u0631\u06cc\u0646 \u06a9\u06d5\u0633 \u0628\u0648\u0648."','Mamar said: "Al-Zuhri traveled to Sham and he was the most knowledgeable."'],t.w)
B.a9w=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0634\u0647\u0627\u0628 \u0627\u0644\u0632\u0647\u0631\u064a: "\u0645\u0627 \u0627\u0633\u062a\u0648\u062f\u0639\u062a \u0642\u0644\u0628\u064a \u0634\u064a\u0626\u0627\u064b \u0641\u0646\u0633\u064a\u062a\u0647."','\u0632\u0648\u0647\u0631\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0647\u06cc\u0686\u0645 \u062e\u0633\u062a\u06d5 \u0646\u0627\u0648 \u062f\u06b5\u0645 \u0648 \u0644\u06d5\u0628\u06cc\u0631\u0645 \u0646\u06d5\u0686\u0648\u0648."','Al-Zuhri said: "I never stored anything in my heart and forgot it."'],t.w)
B.a8U=new A.C(B.r,['\u0642\u0627\u0644 \u0633\u0627\u0644\u0645 \u0628\u0646 \u0639\u0628\u062f\u0627\u0644\u0644\u0647: "\u0645\u0627 \u0623\u062d\u0628\u0628\u062a \u0623\u0646 \u064a\u0643\u0648\u0646 \u0644\u064a \u0641\u064a \u0627\u0644\u062c\u0646\u0629 \u0634\u064a\u0621 \u0644\u0645 \u064a\u0643\u0646 \u0644\u0623\u0628\u064a."','\u0633\u0627\u0644\u0645 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0646\u06d5\u0645\u0648\u06cc\u0633\u062a \u0647\u06cc\u0686\u0645 \u0644\u06d5 \u0628\u06d5\u0647\u06d5\u0634\u062a \u0647\u06d5\u0628\u06ce\u062a \u06a9\u06d5 \u0628\u0627\u0648\u06a9\u0645 \u0646\u06d5\u06cc\u0628\u0648\u0648."','Salim said: "I did not want anything in Paradise that my father did not have."'],t.w)
B.a9x=new A.C(B.r,['\u0642\u0627\u0644 \u0646\u0627\u0641\u0639: "\u0643\u0627\u0646 \u0627\u0628\u0646 \u0639\u0645\u0631 \u0625\u0630\u0627 \u0623\u0639\u062c\u0628\u0647 \u0634\u064a\u0621 \u0645\u0646 \u0645\u0627\u0644\u0647 \u062a\u0635\u062f\u0642 \u0628\u0647."','\u0646\u0627\u0641\u0639 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0627\u0628\u0646 \u0639\u0648\u0645\u06d5\u0631 \u06a9\u0627\u062a\u06ce\u06a9 \u0634\u062a\u06ce\u06a9\u06cc \u0644\u06d5 \u0645\u0627\u06b5\u06d5\u06a9\u06d5\u06cc \u062f\u06b5\u06cc \u067e\u06ce \u062e\u06c6\u0634 \u062f\u06d5\u0628\u0648\u0648\u060c \u0628\u06d5\u062e\u0634\u06cc \u0648\u06d5\u06a9 \u0635\u06d5\u062f\u06d5\u0642\u06d5."','Nafi said: "When Ibn Umar liked something of his wealth, he gave it as charity."'],t.w)
B.a8E=new A.C(B.r,['\u0642\u0627\u0644 \u0639\u0631\u0648\u0629 \u0628\u0646 \u0627\u0644\u0632\u0628\u064a\u0631: "\u0631\u0628 \u0643\u0644\u0645\u0629 \u0630\u0644 \u0633\u0645\u0639\u062a\u0647\u0627 \u0623\u0648\u0631\u062b\u062a\u0646\u064a \u0639\u0632\u0627\u064b."','\u0639\u0648\u0631\u06d5\u0648\u06d5 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0686\u06d5\u0646\u062f\u06d5 \u0648\u0634\u06d5\u06cc\u06d5\u06a9\u06cc \u062e\u0648\u0627\u0631\u06cc\u06cc\u0645 \u0628\u06cc\u0633\u062a\u0648\u0648\u06d5 \u06a9\u06d5 \u0633\u06d5\u0631\u0628\u06d5\u0631\u0632\u06cc\u0645 \u0628\u06d5\u062e\u0634\u06cc\u0648\u06d5."','Urwa said: "Many a humiliating word I heard gave me honor."'],t.w)
B.abs=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u0642\u0627\u0633\u0645 \u0628\u0646 \u0645\u062d\u0645\u062f: "\u0645\u0627 \u0623\u0639\u062c\u0628\u0646\u064a \u0645\u0646 \u0646\u0641\u0633\u064a \u0634\u064a\u0621 \u0623\u062d\u0628 \u0625\u0644\u064a \u0645\u0646 \u0623\u0646 \u0623\u0633\u062a\u0631 \u0639\u0644\u0649 \u0627\u0644\u0646\u0627\u0633."','\u0642\u0627\u0633\u0645 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0647\u06cc\u0686 \u0634\u062a\u06ce\u06a9\u0645 \u0644\u06d5 \u062e\u06c6\u0645 \u067e\u06ce \u062e\u06c6\u0634 \u0646\u06d5\u0628\u0648\u0648\u06d5 \u0648\u06d5\u06a9 \u062f\u0627\u067e\u06c6\u0634\u06cc\u0646\u06cc \u062e\u06d5\u06b5\u06a9."','Al-Qasim said: "Nothing pleased me more than covering people faults."'],t.w)
B.acv=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u0628\u0643\u0631 \u0628\u0646 \u0639\u064a\u0627\u0634: "\u0645\u0627 \u0631\u0627\u062c\u0639\u062a \u0627\u0644\u0642\u0631\u0622\u0646 \u0645\u0646\u0630 \u0623\u0631\u0628\u0639\u064a\u0646 \u0633\u0646\u0629 \u0625\u0644\u0627 \u0641\u064a \u0627\u0644\u0645\u0635\u062d\u0641."','\u0626\u06d5\u0628\u0648 \u0628\u06d5\u06a9\u0631 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0644\u06d5 \u0686\u0644 \u0633\u0627\u06b5 \u0646\u06d5\u0645\u06af\u06d5\u0695\u0627\u0648\u06d5\u062a\u06d5\u0648\u06d5 \u0628\u06c6 \u0642\u0648\u0631\u0626\u0627\u0646 \u062c\u06af\u06d5 \u0644\u06d5 \u0645\u0648\u0633\u062d\u06d5\u0641."','Abu Bakr said: "I have not reviewed Quran for forty years except from the Mushaf."'],t.w)
B.abY=new A.C(B.r,['\u0642\u0627\u0644 \u0633\u0641\u064a\u0627\u0646: "\u0643\u0627\u0646 \u0627\u0644\u0631\u062c\u0644 \u0625\u0630\u0627 \u0637\u0644\u0628 \u0627\u0644\u0639\u0644\u0645 \u0644\u064f\u062d\u0638 \u0639\u0644\u064a\u0647 \u0641\u064a \u062a\u0648\u0627\u0636\u0639\u0647 \u0648\u062e\u0634\u0648\u0639\u0647."','\u0633\u0648\u0641\u06cc\u0627\u0646 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u06a9\u0627\u062a\u06ce\u06a9 \u06a9\u06d5\u0633\u06ce\u06a9 \u0632\u0627\u0646\u0633\u062a\u06cc \u062f\u06d5\u062e\u0648\u06ce\u0646\u062f\u060c \u0644\u06d5 \u062e\u0627\u06a9\u0633\u0627\u0631\u06cc\u06cc\u06d5\u06a9\u06d5\u06cc \u062f\u06d5\u0628\u06cc\u0646\u0631\u0627."','Sufyan said: "When a man sought knowledge, it showed in his humility."'],t.w)
B.aaV=new A.C(B.r,['\u0642\u0627\u0644 \u0645\u0639\u0631\u0648\u0641 \u0627\u0644\u0643\u0631\u062e\u064a: "\u0643\u0644\u0627\u0645 \u0627\u0644\u0639\u0627\u0631\u0641\u064a\u0646 \u0625\u0634\u0627\u0631\u0629\u060c \u0641\u0625\u0630\u0627 \u0635\u0627\u0631 \u0639\u0628\u0627\u0631\u0629 \u0641\u0647\u0648 \u0638\u0644\u0645\u0629."','\u0645\u06d5\u0639\u0631\u0648\u0641 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0642\u0633\u06d5\u06cc \u0632\u0627\u0646\u0627\u06a9\u0627\u0646 \u0626\u0627\u0645\u0627\u0698\u06d5\u06cc\u06d5\u060c \u0626\u06d5\u06af\u06d5\u0631 \u0628\u0628\u06ce\u062a \u0628\u06d5 \u062f\u06d5\u0631\u0628\u0695\u06cc\u0646 \u062a\u0627\u0631\u06cc\u06a9\u06cc\u06cc\u06d5."','Maruf said: "The speech of the knowers is indication; if it becomes description, it is darkness."'],t.w)
B.a9b=new A.C(B.r,['\u0642\u0627\u0644 \u0630\u0648 \u0627\u0644\u0646\u0648\u0646: "\u0645\u0646 \u0639\u0644\u0627\u0645\u0627\u062a \u0627\u0644\u0625\u062e\u0644\u0627\u0635: \u0646\u0633\u064a\u0627\u0646 \u0631\u0624\u064a\u0629 \u0627\u0644\u062e\u0644\u0642."','\u0632\u0648\u0646\u0646\u0648\u0646 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0646\u06cc\u0634\u0627\u0646\u06d5\u06cc \u062f\u06b5\u0633\u06c6\u0632\u06cc: \u0644\u06d5\u0628\u06cc\u0631\u06a9\u0631\u062f\u0646\u06cc \u0633\u06d5\u06cc\u0631\u06cc \u06a9\u06d5\u0633\u06d5\u06a9\u0627\u0646\u06d5."','Dhun-Nun said: "A sign of sincerity is forgetting the sight of people."'],t.w)
B.a8B=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u062d\u0627\u0645\u062f \u0627\u0644\u063a\u0632\u0627\u0644\u064a: "\u0623\u0643\u062b\u0631 \u0627\u0644\u0646\u0627\u0633 \u0634\u0643\u0627\u064b \u0641\u064a \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u0627\u0644\u0641\u0642\u0647\u0627\u0621 \u0627\u0644\u0645\u062a\u062c\u0631\u062f\u0648\u0646 \u0639\u0646 \u0627\u0644\u062d\u0642\u0627\u0626\u0642."','\u063a\u06d5\u0632\u0627\u0644\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0632\u06c6\u0631\u062a\u0631\u06cc\u0646 \u06a9\u06d5\u0633\u0627\u0646 \u06af\u0648\u0645\u0627\u0646\u06cc\u0627\u0646 \u0644\u06d5 \u0642\u06cc\u0627\u0645\u06d5 \u0641\u06cc\u0642\u0647\u0632\u0627\u0646\u06d5\u06a9\u0627\u0646\u0646 \u06a9\u06d5 \u0644\u06d5 \u0695\u0627\u0633\u062a\u06cc\u06cc\u06d5\u06a9\u0627\u0646 \u062f\u0648\u0648\u0631\u0646."','Al-Ghazali said: "Most doubtful of resurrection are jurists stripped of realities."'],t.w)
B.ab2=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u0645\u062f\u064a\u0646: "\u0645\u0646 \u0644\u0645 \u064a\u062e\u0641 \u0641\u064a \u0628\u0627\u0637\u0646\u0647 \u0644\u0645 \u064a\u062d\u062a\u0631\u0645 \u0641\u064a \u0638\u0627\u0647\u0631\u0647."','\u0626\u06d5\u0628\u0648 \u0645\u06d5\u062f\u06cc\u06d5\u0646 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u0644\u06d5 \u0646\u0627\u0648\u06d5\u0648\u06d5 \u0646\u06d5\u062a\u0631\u0633\u06ce\u062a\u060c \u0644\u06d5 \u062f\u06d5\u0631\u06d5\u0648\u06d5 \u0695\u06ce\u0632 \u0644\u06ce \u0646\u0627\u06af\u06cc\u0631\u06ce\u062a."','Abu Madyan said: "Who does not fear inwardly is not respected outwardly."'],t.w)
B.a8m=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0639\u0631\u0628\u064a: "\u0627\u0644\u0639\u0627\u0631\u0641 \u064a\u0631\u0649 \u0627\u0644\u062d\u0642 \u0641\u064a \u0643\u0644 \u0634\u064a\u0621."','\u0627\u0628\u0646 \u0639\u06d5\u0631\u06d5\u0628\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0632\u0627\u0646\u0627 \u0695\u0627\u0633\u062a\u06cc\u06cc\u06d5\u06a9\u06d5 \u0644\u06d5 \u0647\u06d5\u0645\u0648\u0648 \u0634\u062a\u06ce\u06a9 \u062f\u06d5\u0628\u06cc\u0646\u06ce\u062a."','Ibn Arabi said: "The knower sees truth in everything."'],t.w)
B.a9k=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u062d\u0627\u0631\u062b \u0627\u0644\u0645\u062d\u0627\u0633\u0628\u064a: "\u0645\u0646 \u0644\u0645 \u064a\u062d\u0627\u0633\u0628 \u0646\u0641\u0633\u0647 \u0646\u062f\u0645."','\u062d\u0627\u0631\u0633 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u062e\u06c6\u06cc \u0644\u06d5\u0628\u06d5\u0631 \u0686\u0627\u0648 \u0646\u06d5\u06af\u0631\u06ce\u062a \u067e\u06d5\u0634\u06cc\u0645\u0627\u0646 \u062f\u06d5\u0628\u06ce\u062a."','Al-Harith said: "Who does not hold himself accountable will regret."'],t.w)
B.a9s=new A.C(B.r,['\u0642\u0627\u0644 \u0628\u0634\u0631 \u0627\u0644\u062d\u0627\u0641\u064a: "\u0644\u064a\u0633 \u0645\u0646 \u0623\u0639\u0644\u0627\u0645 \u0627\u0644\u062d\u0628 \u0623\u0646 \u062a\u062d\u0628 \u0645\u0627 \u064a\u0628\u063a\u0636 \u062d\u0628\u064a\u0628\u0643."','\u0628\u0634\u0631 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0646\u06cc\u0634\u0627\u0646\u06d5\u06cc \u062e\u06c6\u0634\u06d5\u0648\u06cc\u0633\u062a\u06cc \u0646\u06cc\u06cc\u06d5 \u062d\u06d5\u0632 \u0644\u06d5\u0648\u06d5 \u0628\u06a9\u06d5\u06cc\u062a \u06a9\u06d5 \u062e\u06c6\u0634\u06d5\u0648\u06cc\u0633\u062a\u06d5\u06a9\u06d5\u062a \u0695\u0642\u06cc \u0644\u06ce\u06cc\u06d5."','Bishr said: "It is not a sign of love to love what your beloved hates."'],t.w)
B.a9A=new A.C(B.r,['\u0642\u0627\u0644 \u0631\u0627\u0628\u0639\u0629 \u0627\u0644\u0639\u062f\u0648\u064a\u0629: "\u0623\u062d\u0628\u0643 \u062d\u0628\u064a\u0646\u060c \u062d\u0628 \u0627\u0644\u0647\u0648\u0649 \u0648\u062d\u0628\u0627\u064b \u0644\u0623\u0646\u0643 \u0623\u0647\u0644 \u0644\u0630\u0644\u0643."','\u0695\u0627\u0628\u0639\u06d5 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u062d\u06d5\u0632\u0645 \u0644\u06ce\u062a\u06d5 \u062f\u0648\u0648 \u062d\u06d5\u0632\u060c \u062d\u06d5\u0632\u06cc \u0626\u0627\u0631\u06d5\u0632\u0648\u0648 \u0648 \u062d\u06d5\u0632\u06ce\u06a9 \u0686\u0648\u0646\u06a9\u06d5 \u0634\u0627\u06cc\u0633\u062a\u06d5\u06cc \u0644\u06ce\u06cc\u062a."','Rabia said: "I love You two loves: the love of longing and love because You deserve it."'],t.w)
B.a8f=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u062d\u0644\u0627\u062c: "\u0645\u0627 \u0631\u0623\u064a\u062a \u0634\u064a\u0626\u0627\u064b \u0625\u0644\u0627 \u0631\u0623\u064a\u062a \u0627\u0644\u0644\u0647 \u0641\u064a\u0647."','\u062d\u06d5\u0644\u0644\u0627\u062c \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0647\u06cc\u0686\u0645 \u0646\u06d5\u0628\u06cc\u0646\u06cc \u062c\u06af\u06d5 \u0644\u06d5\u0648\u06d5\u06cc \u062e\u0648\u0627\u0645 \u062a\u06ce\u06cc\u062f\u0627 \u0628\u06cc\u0646\u06cc."','Al-Hallaj said: "I have not seen anything without seeing Allah in it."'],t.w)
B.a8V=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u0637\u0627\u0644\u0628 \u0627\u0644\u0645\u0643\u064a: "\u0627\u0644\u0642\u0644\u0648\u0628 \u062a\u062d\u064a\u0627 \u0628\u0630\u0643\u0631 \u0639\u0644\u0627\u0645 \u0627\u0644\u063a\u064a\u0648\u0628."','\u0626\u06d5\u0628\u0648 \u062a\u0627\u0644\u0628 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u062f\u06b5\u06d5\u06a9\u0627\u0646 \u0628\u06d5 \u06cc\u0627\u062f\u06cc \u0632\u0627\u0646\u0627\u06cc \u0646\u06d5\u0628\u06cc\u0646\u0631\u0627\u0648\u06d5\u06a9\u0627\u0646 \u062f\u06d5\u0698\u06cc\u0646."','Abu Talib said: "Hearts live by remembering the Knower of the unseen."'],t.w)
B.a8l=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u0646\u0639\u064a\u0645: "\u0627\u0644\u062d\u0644\u064a\u0629 \u062d\u0644\u064a\u0629 \u0627\u0644\u0642\u0644\u0628 \u0644\u0627 \u062d\u0644\u064a\u0629 \u0627\u0644\u0628\u062f\u0646."','\u0626\u06d5\u0628\u0648 \u0646\u0648\u0639\u06d5\u06cc\u0645 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u062c\u0648\u0627\u0646\u06a9\u0627\u0631\u06cc \u062c\u0648\u0627\u0646\u06a9\u0627\u0631\u06cc \u062f\u06b5\u06d5 \u0646\u06d5\u06a9 \u062c\u06d5\u0633\u062a\u06d5."','Abu Nuaym said: "Adornment is for the heart not the body."'],t.w)
B.a96=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u062d\u0632\u0645: "\u0644\u0627 \u064a\u062d\u0628 \u0623\u062d\u062f \u0634\u064a\u0626\u0627\u064b \u0625\u0644\u0627 \u0639\u064f\u0631\u0641 \u0630\u0644\u0643 \u0641\u064a \u0639\u064a\u0646\u064a\u0647."','\u0627\u0628\u0646 \u062d\u06d5\u0632\u0645 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0647\u06cc\u0686 \u06a9\u06d5\u0633\u06ce\u06a9 \u062d\u06d5\u0632 \u0644\u06d5 \u0634\u062a\u06ce\u06a9 \u0646\u0627\u06a9\u0627\u062a \u062c\u06af\u06d5 \u0644\u06d5\u0648\u06d5\u06cc \u0644\u06d5 \u0686\u0627\u0648\u06d5\u06a9\u0627\u0646\u06cc \u0628\u0632\u0627\u0646\u0631\u06ce\u062a."','Ibn Hazm said: "No one loves something without it showing in their eyes."'],t.w)
B.ac8=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u0642\u0634\u064a\u0631\u064a: "\u0627\u0644\u062a\u0635\u0648\u0641 \u0627\u0644\u062f\u062e\u0648\u0644 \u0641\u064a \u0643\u0644 \u062e\u0644\u0642 \u0633\u0646\u064a \u0648\u0627\u0644\u062e\u0631\u0648\u062c \u0645\u0646 \u0643\u0644 \u062e\u0644\u0642 \u062f\u0646\u064a."','\u0642\u0648\u0634\u06d5\u06cc\u0631\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u062a\u06d5\u0633\u06d5\u0648\u0641 \u0686\u0648\u0648\u0646\u06d5 \u0646\u0627\u0648 \u0647\u06d5\u0645\u0648\u0648 \u0626\u06d5\u062e\u0644\u0627\u0642\u06ce\u06a9\u06cc \u0628\u0627\u0634 \u0648 \u062f\u06d5\u0631\u0686\u0648\u0648\u0646 \u0644\u06d5 \u0647\u06d5\u0645\u0648\u0648 \u0626\u06d5\u062e\u0644\u0627\u0642\u06ce\u06a9\u06cc \u062e\u0631\u0627\u067e."','Al-Qushayri said: "Sufism is entering every good character and leaving every bad one."'],t.w)
B.a8T=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u0643\u0644\u0627\u0628\u0627\u0630\u064a: "\u0627\u0644\u062a\u0635\u0648\u0641 \u0627\u0633\u062a\u063a\u0631\u0627\u0642 \u0641\u064a \u0627\u0644\u0639\u0628\u0648\u062f\u064a\u0629."','\u06a9\u06d5\u0644\u0627\u0628\u0627\u0632\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u062a\u06d5\u0633\u06d5\u0648\u0641 \u0646\u0648\u0642\u0648\u0645\u0628\u0648\u0648\u0646 \u0644\u06d5 \u0628\u06d5\u0646\u062f\u0627\u06cc\u06d5\u062a\u06cc\u06cc\u06d5."','Al-Kalabadhi said: "Sufism is immersion in servitude."'],t.w)
B.a9H=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u0633\u0647\u0631\u0648\u0631\u062f\u064a: "\u0637\u0631\u064a\u0642\u0646\u0627 \u0637\u0631\u064a\u0642 \u0627\u0644\u062c\u0645\u0639."','\u0633\u0648\u0647\u0631\u06d5\u0648\u06d5\u0631\u062f\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0695\u06ce\u06af\u0627\u06cc \u0626\u06ce\u0645\u06d5 \u0695\u06ce\u06af\u0627\u06cc \u06a9\u06c6\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc\u06d5."','Al-Suhrawardi said: "Our path is the path of gathering."'],t.w)
B.a9X=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u0627\u0644\u0628\u0631\u0643\u0627\u062a: "\u0627\u0644\u0639\u0644\u0645 \u0646\u0648\u0631 \u0641\u064a \u0627\u0644\u0642\u0644\u0628 \u0644\u0627 \u062d\u0641\u0638 \u0641\u064a \u0627\u0644\u0635\u062f\u0631."','\u0626\u06d5\u0628\u0648\u0648\u0644\u0628\u06d5\u0631\u06d5\u06a9\u0627\u062a \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0632\u0627\u0646\u0633\u062a \u0695\u0648\u0646\u0627\u06a9\u06cc\u06cc\u06d5 \u0644\u06d5 \u062f\u06b5 \u0646\u06d5\u06a9 \u062d\u06cc\u0641\u0632 \u0644\u06d5 \u0633\u0646\u06af."','Abu al-Barakat said: "Knowledge is light in the heart not memorization in the chest."'],t.w)
B.abA=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u0634\u0639\u0631\u0627\u0646\u064a: "\u0627\u0644\u0639\u0627\u0631\u0641 \u0645\u0646 \u0634\u0647\u062f \u0631\u0628\u0647 \u0641\u064a \u0643\u0644 \u0634\u064a\u0621."','\u0634\u06d5\u0639\u0631\u0627\u0646\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0632\u0627\u0646\u0627 \u0626\u06d5\u0648\u06d5\u06cc\u06d5 \u067e\u06d5\u0631\u0648\u06d5\u0631\u062f\u06af\u0627\u0631\u06cc \u0644\u06d5 \u0647\u06d5\u0645\u0648\u0648 \u0634\u062a\u06ce\u06a9 \u0628\u0628\u06cc\u0646\u06ce\u062a."','Al-Sharani said: "The knower witnesses his Lord in everything."'],t.w)
B.a8u=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0627\u0644\u0641\u0627\u0631\u0636: "\u0648\u0643\u0644 \u0627\u0644\u062d\u0633\u0646 \u0641\u064a \u0627\u0644\u0643\u0648\u0646 \u0645\u0646 \u062c\u0645\u0627\u0644\u0647\u0627."','\u0627\u0628\u0646 \u0641\u0627\u0631\u0632 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0647\u06d5\u0645\u0648\u0648 \u062c\u0648\u0627\u0646\u06cc \u0644\u06d5 \u06af\u06d5\u0631\u062f\u0648\u0648\u0646 \u0644\u06d5 \u062c\u0648\u0627\u0646\u06cc\u06cc\u06d5\u06a9\u06d5\u06cc\u06d5\u062a\u06cc."','Ibn al-Farid said: "All beauty in existence is from His beauty."'],t.w)
B.aay=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0633\u0628\u0639\u064a\u0646: "\u0627\u0644\u0648\u062d\u062f\u0629 \u0623\u0635\u0644 \u0643\u0644 \u0645\u0648\u062c\u0648\u062f."','\u0627\u0628\u0646 \u0633\u06d5\u0628\u0639\u06cc\u0646 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u06cc\u06d5\u06a9\u06ce\u062a\u06cc \u0695\u06cc\u0634\u06d5\u06cc \u0647\u06d5\u0645\u0648\u0648 \u0628\u0648\u0648\u0646\u06ce\u06a9\u06d5."','Ibn Sabin said: "Unity is the origin of all existence."'],t.w)
B.aa6=new A.C(B.r,['\u0642\u0627\u0644 \u0639\u0628\u062f\u0627\u0644\u0643\u0631\u064a\u0645 \u0627\u0644\u062c\u064a\u0644\u064a: "\u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0645\u0631\u0622\u0629 \u0627\u0644\u062d\u0642."','\u062c\u06cc\u0644\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0645\u0631\u06c6\u06a4 \u0626\u0627\u0648\u06ce\u0646\u06d5\u06cc \u0695\u0627\u0633\u062a\u06cc\u06cc\u06d5."','Al-Jili said: "Man is the mirror of truth."'],t.w)
B.a9u=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u0634\u0627\u0630\u0644\u064a: "\u0645\u0646 \u062f\u0644\u0643 \u0639\u0644\u0649 \u0627\u0644\u062f\u0646\u064a\u0627 \u0641\u0642\u062f \u063a\u0634\u0643\u060c \u0648\u0645\u0646 \u062f\u0644\u0643 \u0639\u0644\u0649 \u0627\u0644\u0639\u0645\u0644 \u0641\u0642\u062f \u0623\u062a\u0639\u0628\u0643."','\u0634\u0627\u0632\u0644\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u0628\u06c6 \u062f\u0648\u0646\u06cc\u0627\u062a \u062f\u06d5\u06b5\u06ce\u0646\u06ce\u062a \u062e\u06d5\u06b5\u06d5\u062a\u0627\u0646\u062f\u0648\u0648\u06cc\u06d5\u062a\u06cc\u060c \u0626\u06d5\u0648\u06d5\u06cc \u0628\u06c6 \u06a9\u0631\u062f\u0627\u0631\u062a \u062f\u06d5\u06b5\u06d5\u0646\u06ce\u062a \u0645\u0627\u0646\u062f\u0648\u0648\u062a \u06a9\u0631\u062f\u0648\u0648\u06d5."','Al-Shadhili said: "Who directs you to the world deceives you; who directs you to work tires you."'],t.w)
B.abw=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u062d\u0645\u062f \u0627\u0644\u0631\u0641\u0627\u0639\u064a: "\u0623\u062d\u0633\u0646 \u0645\u0627 \u064a\u062a\u062e\u0630\u0647 \u0627\u0644\u0639\u0628\u062f \u0632\u0627\u062f\u0627\u064b: \u0642\u0644\u0628 \u062e\u0627\u0634\u0639 \u0648\u0644\u0633\u0627\u0646 \u0630\u0627\u0643\u0631."','\u0695\u06cc\u0641\u0627\u0639\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0628\u0627\u0634\u062a\u0631\u06cc\u0646 \u0632\u0627\u062f\u06cc \u0628\u06d5\u0646\u062f\u06d5: \u062f\u06b5\u06cc \u062e\u0648\u0634\u0648 \u0648 \u0632\u0645\u0627\u0646\u06cc \u06cc\u0627\u062f\u06a9\u06d5\u0631."','Al-Rifai said: "The best provision for a servant: a humble heart and a remembering tongue."'],t.w)
B.a8R=new A.C(B.r,['\u0642\u0627\u0644 \u0639\u0628\u062f\u0627\u0644\u0642\u0627\u062f\u0631 \u0627\u0644\u062c\u064a\u0644\u0627\u0646\u064a: "\u0643\u0646 \u0645\u0639 \u0627\u0644\u062d\u0642 \u0648\u0644\u0627 \u062a\u0628\u0627\u0644."','\u062c\u06cc\u0644\u0627\u0646\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0644\u06d5\u06af\u06d5\u06b5 \u0695\u0627\u0633\u062a\u06cc \u0628\u06d5 \u0648 \u06af\u0648\u06ce\u062a \u0646\u06d5\u0628\u06ce\u062a."','Al-Jilani said: "Be with truth and do not care."'],t.w)
B.aab=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u0628\u0648 \u0627\u0644\u062d\u0633\u0646 \u0627\u0644\u0634\u0627\u0630\u0644\u064a: "\u0627\u0644\u0644\u0647\u0645 \u0627\u062c\u0639\u0644\u0646\u0627 \u0645\u0646 \u0627\u0644\u0630\u064a\u0646 \u062e\u0631\u062c\u0648\u0627 \u0625\u0644\u064a\u0643 \u0641\u0641\u0631\u0648\u0627."','\u0634\u0627\u0632\u0644\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u062e\u0648\u0627\u06cc\u06d5 \u0628\u0645\u0627\u0646\u06a9\u06d5 \u0644\u06d5\u0648 \u06a9\u06d5\u0633\u0627\u0646\u06d5\u06cc \u0628\u06c6 \u0644\u0627\u062a \u062f\u06d5\u0631\u0686\u0648\u0648\u0646 \u0648 \u0695\u0627\u06cc\u0627\u0646\u06a9\u0631\u062f."','Al-Shadhili said: "O Allah, make us of those who went out to You and fled."'],t.w)
B.abn=new A.C(B.r,['\u0642\u0627\u0644 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0627\u0644\u062f\u0633\u0648\u0642\u064a: "\u0627\u0644\u0641\u0642\u064a\u0631 \u0645\u0646 \u063a\u0627\u0628 \u0639\u0646 \u0646\u0641\u0633\u0647 \u0628\u0634\u0647\u0648\u062f \u0631\u0628\u0647."','\u062f\u06d5\u0633\u0648\u0648\u0642\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0647\u06d5\u0698\u0627\u0631 \u0626\u06d5\u0648\u06d5\u06cc\u06d5 \u0644\u06d5 \u062e\u06c6\u06cc \u0646\u06d5\u0628\u06ce\u062a \u0628\u06d5 \u0628\u06cc\u0646\u06cc\u0646\u06cc \u067e\u06d5\u0631\u0648\u06d5\u0631\u062f\u06af\u0627\u0631\u06cc."','Al-Dasuqi said: "The poor is who is absent from himself by witnessing his Lord."'],t.w)
B.aaj=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u062d\u0645\u062f \u0627\u0644\u0628\u062f\u0648\u064a: "\u0627\u0644\u0633\u0639\u064a\u062f \u0645\u0646 \u0639\u0631\u0641 \u0631\u0628\u0647 \u0642\u0628\u0644 \u0627\u0644\u0645\u0645\u0627\u062a."','\u0628\u06d5\u062f\u06d5\u0648\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0628\u06d5\u062e\u062a\u06d5\u0648\u06d5\u0631 \u0626\u06d5\u0648\u06d5\u06cc\u06d5 \u067e\u06d5\u0631\u0648\u06d5\u0631\u062f\u06af\u0627\u0631\u06cc \u0628\u0646\u0627\u0633\u06ce\u062a \u067e\u06ce\u0634 \u0645\u06d5\u0631\u06af."','Al-Badawi said: "Happy is who knows his Lord before death."'],t.w)
B.a90=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0639\u062c\u064a\u0628\u0629: "\u0627\u0644\u0630\u0643\u0631 \u0631\u0648\u062d \u0627\u0644\u0623\u0639\u0645\u0627\u0644."','\u0627\u0628\u0646 \u0639\u06d5\u062c\u06cc\u0628\u06d5 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u06cc\u0627\u062f \u0695\u06c6\u062d\u06cc \u06a9\u0631\u062f\u0627\u0631\u06d5\u06a9\u0627\u0646\u06d5."','Ibn Ajiba said: "Remembrance is the spirit of actions."'],t.w)
B.a9e=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u062f\u0631\u0642\u0627\u0648\u064a: "\u0627\u0644\u0639\u0632\u0644\u0629 \u0639\u0646 \u0623\u0647\u0644 \u0627\u0644\u063a\u0641\u0644\u0629 \u062d\u0635\u0646."','\u062f\u06d5\u0631\u0642\u0627\u0648\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u062f\u0648\u0648\u0631\u0628\u0648\u0648\u0646 \u0644\u06d5 \u062e\u06d5\u06b5\u06a9\u06cc \u063a\u06d5\u0641\u06b5\u06d5\u062a \u0642\u06d5\u06b5\u0627\u06cc\u06d5."','Al-Darqawi said: "Isolation from heedless people is a fortress."'],t.w)
B.aaG=new A.C(B.r,['\u0642\u0627\u0644 \u0623\u062d\u0645\u062f \u0632\u0631\u0648\u0642: "\u0627\u0644\u062a\u0635\u0648\u0641 \u0639\u0644\u0645 \u064a\u0639\u0631\u0641 \u0628\u0647 \u0623\u062d\u0648\u0627\u0644 \u062a\u0632\u0643\u064a\u0629 \u0627\u0644\u0646\u0641\u0633."','\u0632\u06d5\u0695\u0648\u0648\u0642 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u062a\u06d5\u0633\u06d5\u0648\u0641 \u0632\u0627\u0646\u0633\u062a\u06ce\u06a9\u06d5 \u06a9\u06d5 \u0628\u0627\u0631 \u0648 \u062f\u06c6\u062e\u06cc \u067e\u0627\u06a9\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc \u0646\u06d5\u0641\u0633\u06cc \u067e\u06ce \u062f\u06d5\u0646\u0627\u0633\u0631\u06ce\u062a."','Zarruq said: "Sufism is knowing the states of purifying the soul."'],t.w)
B.aa4=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u0634\u064a\u062e \u0623\u062d\u0645\u062f \u0627\u0644\u062a\u062c\u0627\u0646\u064a: "\u0645\u0646 \u0623\u062e\u0644\u0635 \u0644\u0644\u0647 \u0641\u064a \u0623\u0645\u0648\u0631\u0647 \u0627\u0646\u0641\u062a\u062d\u062a \u0644\u0647 \u0623\u0628\u0648\u0627\u0628 \u0627\u0644\u0633\u0639\u0627\u062f\u0629."','\u062a\u06cc\u062c\u0627\u0646\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u062f\u06b5\u0633\u06c6\u0632 \u0628\u06ce\u062a \u0628\u06c6 \u062e\u0648\u0627 \u0644\u06d5 \u06a9\u0627\u0631\u06d5\u06a9\u0627\u0646\u06cc\u060c \u062f\u06d5\u0631\u06af\u0627\u06cc \u0628\u06d5\u062e\u062a\u06d5\u0648\u06d5\u0631\u06cc \u0628\u06c6 \u062f\u06d5\u06a9\u0631\u06ce\u062a\u06d5\u0648\u06d5."','Al-Tijani said: "Who is sincere to Allah in his affairs, doors of happiness open."'],t.w)
B.a9J=new A.C(B.r,['\u0642\u0627\u0644 \u0645\u062d\u064a \u0627\u0644\u062f\u064a\u0646 \u0627\u0628\u0646 \u0639\u0631\u0628\u064a: "\u0645\u0627 \u062b\u0645\u0629 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647."','\u0627\u0628\u0646 \u0639\u06d5\u0631\u06d5\u0628\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0647\u06cc\u0686 \u0646\u06cc\u06cc\u06d5 \u062c\u06af\u06d5 \u0644\u06d5 \u062e\u0648\u0627."','Ibn Arabi said: "There is nothing but Allah."'],t.w)
B.abm=new A.C(B.r,['\u0642\u0627\u0644 \u0639\u0628\u062f\u0627\u0644\u0648\u0647\u0627\u0628 \u0627\u0644\u0634\u0639\u0631\u0627\u0646\u064a: "\u0645\u064a\u0632\u0627\u0646 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0634\u0631\u064a\u0639\u0629."','\u0634\u06d5\u0639\u0631\u0627\u0646\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u06a9\u06ce\u0634\u06cc \u0695\u06ce\u06af\u0627 \u0634\u06d5\u0631\u06cc\u0639\u06d5\u062a\u06d5."','Al-Sharani said: "The measure of the path is the Sharia."'],t.w)
B.a8k=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u0625\u0645\u0627\u0645 \u0627\u0644\u0633\u064a\u0648\u0637\u064a: "\u0627\u0644\u0639\u0644\u0645 \u0623\u0645\u0627\u0646\u0629 \u0641\u0645\u0646 \u0643\u062a\u0645\u0647 \u0641\u0642\u062f \u062e\u0627\u0646."','\u0633\u06cc\u0648\u0648\u062a\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0632\u0627\u0646\u0633\u062a \u0626\u06d5\u0645\u0627\u0646\u06d5\u062a\u06d5\u060c \u0626\u06d5\u0648\u06d5\u06cc \u0628\u06cc\u0634\u0627\u0631\u06ce\u062a\u06d5\u0648\u06d5 \u062e\u06cc\u0627\u0646\u06d5\u062a\u06cc \u06a9\u0631\u062f\u0648\u0648\u06d5."','Al-Suyuti said: "Knowledge is a trust; who conceals it has betrayed."'],t.w)
B.aby=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u062d\u062c\u0631 \u0627\u0644\u0639\u0633\u0642\u0644\u0627\u0646\u064a: "\u0637\u0627\u0644\u0628 \u0627\u0644\u0639\u0644\u0645 \u0644\u0627 \u064a\u0645\u0644."','\u0627\u0628\u0646 \u062d\u06d5\u062c\u06d5\u0631 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u062e\u0648\u06ce\u0646\u062f\u06a9\u0627\u0631\u06cc \u0632\u0627\u0646\u0633\u062a \u0646\u0627\u0645\u0627\u0646\u062f\u0648\u0648 \u062f\u06d5\u0628\u06ce\u062a."','Ibn Hajar said: "The seeker of knowledge does not tire."'],t.w)
B.a97=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0644\u0646\u0648\u0648\u064a: "\u0645\u0646 \u0644\u0632\u0645 \u0627\u0644\u0627\u0633\u062a\u063a\u0641\u0627\u0631 \u062c\u0639\u0644 \u0627\u0644\u0644\u0647 \u0644\u0647 \u0645\u0646 \u0643\u0644 \u0647\u0645 \u0641\u0631\u062c\u0627\u064b."','\u0646\u06d5\u0648\u06d5\u0648\u06cc \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u0628\u06d5 \u0626\u0633\u062a\u063a\u0641\u0627\u0631 \u0628\u0686\u06d5\u0633\u067e\u06ce\u062a\u060c \u062e\u0648\u0627 \u0644\u06d5 \u0647\u06d5\u0645\u0648\u0648 \u062e\u06d5\u0645 \u0641\u06d5\u0631\u0627\u0647\u0627\u0646\u062f\u0646\u06cc \u067e\u06ce \u062f\u06d5\u0628\u06d5\u062e\u0634\u06ce\u062a."','Al-Nawawi said: "Who adheres to seeking forgiveness, Allah gives him relief from every worry."'],t.w)
B.a95=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u0627\u0644\u0642\u064a\u0645: "\u0641\u064a \u0627\u0644\u0642\u0644\u0628 \u0634\u0639\u062b \u0644\u0627 \u064a\u0644\u0645\u0647 \u0625\u0644\u0627 \u0627\u0644\u0625\u0642\u0628\u0627\u0644 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647."','\u0627\u0628\u0646 \u0642\u06d5\u06cc\u0645 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0644\u06d5 \u062f\u06b5\u062f\u0627 \u067e\u06d5\u0631\u0627\u0648\u06ce\u0632\u06cc \u0647\u06d5\u06cc\u06d5 \u062a\u06d5\u0646\u0647\u0627 \u0695\u0648\u0648\u06a9\u0631\u062f\u0646 \u0628\u06c6 \u062e\u0648\u0627 \u0695\u06ce\u06a9\u06cc \u062f\u06d5\u062e\u0627\u062a."','Ibn al-Qayyim said: "The heart has a scatteredness that only turning to Allah can mend."'],t.w)
B.a8J=new A.C(B.r,['\u0642\u0627\u0644 \u0627\u0628\u0646 \u062a\u064a\u0645\u064a\u0629: "\u0645\u0646 \u0623\u0639\u0631\u0636 \u0639\u0646 \u0627\u0644\u062d\u0642 \u0627\u0628\u062a\u0644\u0627\u0647 \u0627\u0644\u0644\u0647 \u0628\u0627\u0644\u0628\u0627\u0637\u0644."','\u0627\u0628\u0646 \u062a\u06d5\u06cc\u0645\u06cc\u06d5 \u0641\u06d5\u0631\u0645\u0648\u0648\u06cc\u06d5\u062a\u06cc: "\u0626\u06d5\u0648\u06d5\u06cc \u067e\u0634\u062a\u06cc \u0628\u06a9\u0627\u062a \u0628\u06d5 \u0695\u0627\u0633\u062a\u06cc\u060c \u062e\u0648\u0627 \u0628\u06d5 \u0628\u0627\u062a\u06b5\u06cc \u062a\u0648\u0648\u0634 \u062f\u06d5\u06a9\u0627\u062a."','Ibn Taymiyyah said: "Who turns away from truth, Allah afflicts him with falsehood."'],t.w)
